/* Generado a partir de “Recomendaciones Vigentes 1965-2026”, Oficina de Servicios Generales de AA Colombia.
   c = comité · a = año · k = tipo · t = texto · p = página impresa del documento. */
const ACCIONES = [{"c":"Agenda y Políticas","a":1971,"k":"Recomendación","t":"Se Recomienda que el Informe Final de la Conferencia sea leído por el delegado o por el RSG en reuniones cerradas de grupo. Se Recomienda: Cuando se invite a un custodio a reuniones de aniversario, encuentros, reuniones zonales, etc., debe entenderse que tal invitación se hace a un miembro de AA y no a la persona en su calidad de custodio. Esto en el caso de que el invitado sea un custodio clase B.","p":8},{"c":"Agenda y Políticas","a":1977,"k":"Recomendación","t":"Se Recomienda: Que, en el futuro, la Conferencia se reúna en un sitio más adecuado en la ciudad de Medellín, durante tres días del mes de abril de cada año, de acuerdo con nuestra Carta Constitutiva. El temario será enviado a cada delegado con un mes de anticipación a la reunión anual.","p":8},{"c":"Agenda y Políticas","a":1977,"k":"Recomendación","t":"Se Recomienda: Que a partir de 1978 la Conferencia se reúna durante tres días en el sitio más apropiado que escoja la OSG.","p":8},{"c":"Agenda y Políticas","a":1978,"k":"Recomendación","t":"Recomienda que la OSG informe trimestralmente, por medio del boletín, de sus actividades a los grupos del país.","p":8},{"c":"Agenda y Políticas","a":1980,"k":"Recomendación","t":"Se Recomienda: que a través del boletín debe promoverse la importancia del tema de la Conferencia.","p":8},{"c":"Agenda y Políticas","a":1980,"k":"Recomendación","t":"Se Recomienda: a las Asambleas de Área o Comités de servicio, hacer llegar a la OSG, con la anticipación correspondiente un acta en la cual conste la elección del Delegado y las firmas reglamentarias.","p":8},{"c":"Agenda y Políticas","a":1980,"k":"Recomendación","t":"Se Recomienda: que a todo invitado especial a la Conferencia debe permitírsele participar con voz, no solamente en la presentación del trabajo que se le encomendó, sino también en todas las sesiones de la misma.","p":8},{"c":"Agenda y Políticas","a":1981,"k":"Recomendación","t":"Se Recomienda: Que haya una mayor comunicación entre custodios y delegados a través de la OSG, sobre todo después de las reuniones de la Junta.","p":8},{"c":"Agenda y Políticas","a":1982,"k":"Recomendación","t":"Se Recomienda: que los delegados, grupos y miembros envíen con suficiente anticipación (ojalá antes de finalizar el mes de febrero) todas las inquietudes y Sugerencias que se deseen tratar en la Conferencia. De esta manera se podrá programar mejor el trabajo de cada uno de los comités.","p":9},{"c":"Agenda y Políticas","a":1982,"k":"Recomendación","t":"Se Recomienda: que los miembros de AA que trabajan a sueldo en instituciones dedicadas a la recuperación de alcohólicos, no sean considerados para cargos de servicio en la estructura de AA.","p":9},{"c":"Agenda y Políticas","a":1982,"k":"Recomendación","t":"Se Recomienda: a los servidores que terminan su período que continúen vinculados al servicio activo ya que sus experiencias son de gran utilidad para asesorar a los nuevos servidores.","p":9},{"c":"Agenda y Políticas","a":1982,"k":"Recomendación","t":"Se Recomienda: que el Custodio Clase B, después de completar su período de servicio, no pueda repetir como Custodio de Servicio General, ni viceversa.","p":9},{"c":"Agenda y Políticas","a":1983,"k":"Recomendación","t":"Se Recomienda que sean los congresos y eventos zonales los que se aprovechen para la invitación y la visita de director de la OSG y los custodios a las zonas, para difundir y estructurar mejor el servicio general.","p":9},{"c":"Agenda y Políticas","a":1984,"k":"Recomendación","t":"Se Recomienda: A los grupos de la ciudad sede, rodear de unidad y amor a nuestra OSG para prestar un eficiente apoyo a los distintos comités, para el mejor servicio de Colombia y sus países patrocinados.","p":9},{"c":"Agenda y Políticas","a":1988,"k":"Recomendación","t":"Se Recomienda: que la elección del delegado se efectúe antes del 15 de noviembre. Se Recomienda además la inclusión de un formato que contenga la hoja de vida, con el objeto de que se encuentre oportunamente en el comité de la Conferencia la documentación necesaria del delegado.","p":9},{"c":"Agenda y Políticas","a":1988,"k":"Recomendación","t":"Recomienda: incluir en la agenda de la Conferencia el informe del Custodio de Servicios Generales.","p":9},{"c":"Agenda y Políticas","a":1988,"k":"Recomendación","t":"Se Recomienda: que en el año en que se celebre la Convención Nacional, en reemplazo de los Congresos Zonales se efectúe un foro nacional de servicios, con participación de custodios, ex custodios, delegados, ex coordinadores de comités de área y presidentes de oficinas intergrupales.","p":9},{"c":"Agenda y Políticas","a":1991,"k":"Recomendación","t":"Recomendamos: La creación del Comité de Política de la Conferencia el cual queda anexo al Comité de Agenda.","p":9},{"c":"Agenda y Políticas","a":1991,"k":"Recomendación","t":"Se Recomienda: al Comité sobre Conferencia de la Junta de Custodios el envío a los delegados de un proyecto de agenda de la Conferencia para su aprobación.","p":9},{"c":"Agenda y Políticas","a":1995,"k":"Recomendación","t":"Se Recomienda: Que el mes de enero de cada año sea dedicado al estudio de los Doce Conceptos para el Servicio Mundial en las áreas y grupos de nuestra Comunidad.","p":9},{"c":"Agenda y Políticas","a":2000,"k":"Recomendación","t":"Se Recomienda: que los comités de área y las oficinas de Inter grupos establezcan un trabajo en equipo tratando de buscar la armonía y la unidad, con el fin de que no se presente dualidad en sus funciones y que se acojan a las definidas en el Manual de Servicio de AA.","p":9},{"c":"Agenda y Políticas","a":2001,"k":"Recomendación","t":"Se Recomienda: Que en las próximas conferencias y foros de servicio: nacionales, zonales y de área, se comparta sobre la necesidad y las experiencias de los distritos en nuestra estructura.","p":9},{"c":"Agenda y Políticas","a":2002,"k":"Recomendación","t":"Se Recomienda: Que la Reunión Conjunta de los Comités de Agenda y Políticas de la Junta de Custodios y de la Conferencia, se celebre en la primera quincena de enero, con el fin exclusivo de aprobar la agenda que se desarrollará en la Conferencia que se celebra en ese año.","p":10},{"c":"Agenda y Políticas","a":2004,"k":"Recomendación","t":"Se Recomienda: a las áreas realizar reuniones pre conferencia sobre el lema y los lemas aprobados en la Conferencia.","p":10},{"c":"Agenda y Políticas","a":2004,"k":"Recomendación","t":"Se Recomienda: Que se conforme el Comité de Archivo de la Conferencia de Servicios Generales de Colombia y en cada una de las áreas del país, con el fin de coordinar y proyectar a nivel nacional dentro de la Comunidad, la recolección, dosificación y uso adecuado de documentos, objetos, libros y toda clase de material de importancia histórica que sirva para enriquecer el archivo histórico y administrativo de A.A. en Colombia.","p":10},{"c":"Agenda y Políticas","a":2004,"k":"Recomendación","t":"Se Recomienda: al Comité de Agenda y Políticas de la Junta establecer una fecha límite, para recibir propuestas que serán tomadas en cuenta en los Comités de la Conferencia, con el fin de hacer más dinámico y productivo el proceso de aprobación de las recomendaciones, exceptuando aquellos proyectos que surgen del trabajo colectivo de los Comités de la Conferencia, para los cuales se abre un espacio autorizado por la misma.","p":10},{"c":"Agenda y Políticas","a":2005,"k":"Recomendación","t":"Se Recomienda: reformar el artículo diez de los Estatutos de la Corporación, que para la elección del Custodio de Servicios Generales sea ampliada a las áreas 1 y 3 de la Zona E, así: Deberá residir en la ciudad de Medellín, su área Metropolitana, o en cualquiera de los municipios de las áreas 1 y 3 de la Zona E.","p":10},{"c":"Agenda y Políticas","a":2007,"k":"Recomendación","t":"Se Recomienda: Impulsar y desarrollar los Talleres de Liderazgo Integral en los comités de servicios, (desde el grupo hasta la Junta de Custodios) El proceso de implementación será liderado por los Custodios Zonales y Delegados, con la ayuda logística de la OSG, propendiendo principalmente para que en aquellas zonas, áreas, distritos o grupos donde no se han desarrollado, no se retarde más su implementación.","p":10},{"c":"Agenda y Políticas","a":2009,"k":"Recomendación","t":"Se Recomienda: Que toda Conferencia además del lema establezca una denominación del año.","p":10},{"c":"Agenda y Políticas","a":2009,"k":"Moción","t":"Moción: que la reunión conjunta de los comités de Agenda de la Junta de Custodios y de la Conferencia, se celebre en la primera quincena de enero, con el fin exclusivo de aprobar la agenda que se desarrollará en la Conferencia en ese año. (Recomendación 2002).","p":10},{"c":"Agenda y Políticas","a":2012,"k":"Recomendación","t":"Se Recomienda: Que en la agenda de la CSG se implemente una reunión, previa al inicio de la CSG, encaminada a compartir entre los dos paneles de la CSG, en la cual sólo participen los Delegados.","p":10},{"c":"Agenda y Políticas","a":2015,"k":"Recomendación","t":"Se Recomienda: Dar respuesta a los proyectos de Recomendación por parte de cada comité con las razones por las cuales fueron rechazados.","p":10},{"c":"Agenda y Políticas","a":2015,"k":"Sugerencia","t":"Sugerencia: Que la Junta de Custodios no modifique, y sí lo hace que lo comunique sobre las decisiones tomadas en la reunión de programación de Comité de Agenda de la Conferencia.","p":10},{"c":"Agenda y Políticas","a":2015,"k":"Sugerencia","t":"Sugerencia: Que en la reunión de delegados haya una agenda preestablecida y que se consideren en ella los puntos sobresalientes y preguntas de los informes de los delegados.","p":10},{"c":"Agenda y Políticas","a":2017,"k":"Recomendación","t":"Se Recomienda: Que los lemas que apruebe la Conferencia sean cortos y que se retire la Recomendación del 2009 que dice: Se Recomienda que toda Conferencia además del lema establezca una denominación del año.","p":11},{"c":"Agenda y Políticas","a":2018,"k":"Recomendación","t":"Se Recomienda: Que se incluya en la agenda de la 55ª Conferencia de Servicios Generales el tema “Problemas diferentes al alcoholismo”; para mantener nuestra unicidad de propósito.","p":11},{"c":"Agenda y Políticas","a":2018,"k":"Recomendación","t":"Se Recomienda: Que en todos los doce reportes que se envían durante el año a los delegados, se coloque una nota recordatoria, rememorando, que el programa final de la Conferencia se elabora con propuestas enviadas por la misma comunidad en general; las cuales deben ser enviadas antes del 31 de enero de cada año; para que reposen en la OSG, y de ahí elaborar la agenda de la Conferencia.","p":11},{"c":"Agenda y Políticas","a":2020,"k":"Lema","t":"Lema: “Vivir los Doce Pasos, Fortalece Nuestra Estructura”","p":11},{"c":"Agenda y Políticas","a":2021,"k":"Lema","t":"Lema de la 58 CSG: “El apadrinamiento contribuye al fortalecimiento de nuestra Estructura”.","p":11},{"c":"Agenda y Políticas","a":2022,"k":"Recomendación","t":"Se Recomienda que el lema para la 59ª Conferencia de Servicios Generales sea: “Nuestro Grupo base… donde todo empieza”","p":11},{"c":"Agenda y Políticas","a":2023,"k":"Recomendación","t":"Se Recomienda al Comité de Conferencia de la Junta de Servicios Generales que modifique la Acción Recomendable de la 54 CSG que dice “En todos los doce Reportes que se envían durante el año a los Delegados, se coloque una nota recordatoria, recomendando que el programa final de la Conferencia se elabora con propuestas enviadas por la misma Comunidad. Sustituir esta acción recomendable por la siguiente: “Que en los reportes de la Conferencia que se envían a los delegados durante todo el año, solamente en los reportes del uno (1) al ocho (8) se coloque una nota recordatoria motivando el envió de temas y propuestas para la elaboración de la programación final de la Conferencia (Agenda)”","p":11},{"c":"Agenda y Políticas","a":2024,"k":"Recomendación","t":"Se recomienda: modificar la Acción Recomendable del año 2002 del Comité de Agenda que dice: “que la reunión conjunta de los Comités de Agenda y Política de la Junta de Custodios y de la Conferencia, se celebre en la primera quincena de enero, con el fin exclusivo de aprobar la Agenda que se desarrollará en la Conferencia que se celebra en ese año”, por la siguiente: “Se recomienda que la reunión conjunta entre el Comité de Agenda de la Conferencia y el Comité de Conferencia de Servicios Generales de la Junta de Custodios, se celebre en la primera quincena de febrero, con el fin exclusivo de aprobar la Agenda que se desarrollará en la Conferencia que se celebra en ese año”.","p":11},{"c":"Agenda y Políticas","a":2025,"k":"Sugerencia","t":"Sugerencia: se declare improcedente la Reunión Especial de la Conferencia de Servicios Generales (RECSG), efectuada de manera virtual, los días 19 y 20 de octubre de 2024 ya que desde el momento en que fue convocada, no cumplía con los requisitos necesarios para ser realizada y en su ejecución se pasaron por alto varios principios, así: - Incumplimiento al Artículo 18 de los Estatutos de la CNSGAA no se cumplió con la votación (Mayoría Simple) para que se aprobara la RECSG: Del Quórum de 40 delegados inscritos a la 60 RAC (Artículo 4 Carta Constitutiva): Nueve (9) votaron en contra, (20) a favor y (11) se abstuvieron o no alcanzaron a votar. Si hablamos de mayoría simple debieron ser 21 votos para aprobar o rechazar y esto claramente no se cumplió. El error consiste en que no se recibieron los votos de los 40 delegados inscritos. - Incumplimiento al Artículo 19 de los Estatutos de la CNSGAA la convocatoria de la reunión se debió hacer con dos semanas de anticipación y solo dieron cinco días. - Finalmente, la Reunión Especial de la Conferencia fue grabada y los audios se dieron a conocer a la membresía nacional, en la ejecución de la reunión especial asistieron personas no alcohólicas y además estuvieron al frente del conteo de los votos, esto es una clara violación a nuestro principio de Anonimato.","p":11},{"c":"Agenda y Políticas","a":2025,"k":"Recomendación","t":"Se recomienda: que la Junta de Servicios Generales (JSG) conforme un Comité incluyendo antiguos servidores de la estructura para estudiar, analizar, complementar y actualizar la actual mecánica de la reunión anual de la Conferencia de Servicios Generales (MRAC). Se presentarán tres borradores, así: 1. Se debe entregar hasta el 31 de julio de 2025; 2. Se debe entregar hasta el 30 de noviembre de 2025; 3. Este último se presentará en la RAC de 2026. Una vez la JSG tenga los dos primeros borradores de la MRAC, los compartirá, en las fechas previstas anteriormente, con la conciencia nacional, a través de los delegados, para sus comentarios. Luego de ser aprobada la MRAC se debe aplicar en la RAC, y ser incluida en la siguiente edición del Manual de Servicio de AA de Colombia.","p":12},{"c":"Agenda y Políticas","a":2026,"k":"Recomendación","t":"Se recomienda: prorrogar la recomendación de la MRAC de la RAC para ser aprobada en la RAC # 63. Teniendo en cuenta el trabajo realizado en el segundo borrador, la JSG recibirá sugerencias hasta el 31 de julio de 2026. Una vez que el comité de conferencia de la JSG reciba las sugerencias de la membresía oficializada y sustentada por el Comité de Área respectiva, organizará junto con el comité transitorio el tercer y último borrador de la MRAC que será presentado el 15 de octubre de 2026 al comité de agenda de la conferencia para su revisión final y posterior presentación para la aprobación en la RAC # 63.","p":12},{"c":"Finanzas","a":1969,"k":"Recordatorio","t":"Se recuerda que es la literatura el medio más efectivo para llevar el mensaje, siendo a la vez, una manera de contribuir a los centros de servicio. Obsequie folletos en sus Pasos Doce, en colegios, hospitales; recuerde que con ello está colaborando y retribuyendo. Comprar más literatura: Cada uno de nosotros debiera fijarse la consigna de “compremos literatura”. Que en todos los grupos haya el mayor número de folletos a la vista de los compañeros, para que puedan proveerse de la literatura que deseen. Inscripción para congresos y reuniones especiales: Explicar a los compañeros que al establecer estas inscripciones no se trata de poner precio a la asistencia a nuestras reuniones, sino que se ha hecho para atender los gastos que demandan estos eventos, como también para buscar algún remanente que ayude al mantenimiento de los servicios.","p":12},{"c":"Finanzas","a":1969,"k":"Recomendación","t":"Se Recomienda a los delegados, personalmente y a través de los RSG, hacer conocer a los grupos la necesidad que tenemos todos de cumplir nuestra Tradición Siete de “mantenernos con nuestras propias contribuciones”, entendiendo que ese mantenimiento no es solamente para cubrir los gastos de los grupos, sino también para atender debidamente los que ocasionan el funcionamiento de los inter grupos, y los de la OSG.","p":12},{"c":"Finanzas","a":1969,"k":"Recomendación","t":"Se Recomienda estimular el estudio de la literatura, para que más gente se provea de ella, logrando así mayor venta.","p":12},{"c":"Finanzas","a":1969,"k":"Recomendación","t":"Se Recomienda que personas responsables manejen los dineros de los grupos, para que puedan presentar buenas cuentas y así lograr contribuir a la OSG.","p":13},{"c":"Finanzas","a":1969,"k":"Recomendación","t":"Se Recomienda estar todos vigilando para que no vaya a confundirse nuestra asociación de A.A. con otras organizaciones, muy principalmente en la solicitud de fondos para el funcionamiento de ellas, pues no teniendo éstas, las Tradiciones que nosotros guardamos, pueden libremente pedir ayuda a extraños en dinero y demás facilidades y, por tanto, es nuestro deber vigilar que de ninguna manera vaya a ser usado el nombre de A.A. con esos fines.","p":13},{"c":"Finanzas","a":1973,"k":"Sugerencia","t":"Se sugiere A todos los miembros de A.A. un aporte voluntario mensual con destino a la OSG. La forma de recaudar este aporte queda a criterio de los grupos.","p":13},{"c":"Finanzas","a":1973,"k":"Recomendación","t":"Se Recomienda a los grupos promover la venta de literatura bien sea mediante la exhibición de ella o a través de pequeñas rifas.","p":13},{"c":"Finanzas","a":1973,"k":"Recomendación","t":"Se Recomienda a los delegados, motivar a los grupos para tratar de conseguir una mayor participación de éstos en el mantenimiento de la OSG.","p":13},{"c":"Finanzas","a":1973,"k":"Recomendación","t":"Se Recomienda a la OSG ocuparse en mantener el entusiasmo constante de los grupos del país, recalcándoles la importancia de los aportes; ampliando un poco más la información sobre su estado financiero y dando a conocer sus planes de servicio.","p":13},{"c":"Finanzas","a":1973,"k":"Recomendación","t":"Se Recomienda a los grupos que acojan una Recomendación de la 3º Reunión de Servicio Mundial sobre la recaudación de fondos y que a la letra dice: “Se sugiere que los grupos de A.A. recauden sus fondos sólo por los medios tradicionales (recolectas de grupo) porque al hacerlo en otra forma pueden poner en peligro la sobriedad del individuo, la existencia del grupo y el bienestar de A.A. como un todo”.","p":13},{"c":"Finanzas","a":1976,"k":"Recomendación","t":"Se Recomienda A los grupos y oficinas de servicio local que se abstengan de publicar en las carteleras los nombres de los compañeros que hagan aportes voluntarios para A.A.","p":13},{"c":"Finanzas","a":1977,"k":"Recomendación","t":"Se Recomienda: a los delegados que motiven a los grupos de su área para que aporten a la OSG.","p":13},{"c":"Finanzas","a":1980,"k":"Recomendación","t":"Se Recomienda A los delegados asistentes a la Conferencia promover en sus respectivas áreas: a)El aumento de aportes de los grupos a la OSG; b) El cumplimiento del plan aniversario, y c) Venta de literatura, suscripciones al boletín y la revista “A.A. El Mensaje”.","p":13},{"c":"Finanzas","a":1981,"k":"Recomendación","t":"Se Recomienda: a las oficinas de inter grupos trabajar con el descuento que concede la OSG en ventas de literatura, con el fin de que puedan venderla al mismo precio que la oficina.","p":13},{"c":"Finanzas","a":1982,"k":"Recomendación","t":"Se Recomienda: que a las próximas Conferencias se invite al contador y al revisor fiscal de la Corporación, para que se aclaren aspectos contables y diluciden situaciones financieras de la asociación.","p":13},{"c":"Finanzas","a":1982,"k":"Recomendación","t":"Se Recomienda: a los delegados, R.S.G. y demás servidores informar oportuna y debidamente a todos los grupos del país, sobre los cambios que se registran en los costos de nuestra literatura y los motivos que se operan para los incrementos en su valor.","p":13},{"c":"Finanzas","a":1982,"k":"Recomendación","t":"Se Recomienda: que, para el mes de noviembre, señalado como el “mes de las Tradiciones”, se celebre en todos los grupos de A.A. la “SEMANA DE LA GRATITUD”, como lo sugiere el folleto “El Grupo de A.A.” y que los recaudos que se logren en ellas sean con exclusivo destino para la OSG.","p":14},{"c":"Finanzas","a":1984,"k":"Recomendación","t":"Se Recomienda: Que la semana de la Gratitud que se celebra en el mes de noviembre, mes de las tradiciones, sea promovida por parte de la OSG y comités de área con la suficiente anticipación y por medio de los cuerpos de servicio, a través de boletines y todos los medios posibles de difusión a los grupos.","p":14},{"c":"Finanzas","a":1984,"k":"Recomendación","t":"Se Recomienda: Que, en lo posible, Colombia esté representada en los eventos de servicio mundial y en el Encuentro Iberoamericano.","p":14},{"c":"Finanzas","a":1985,"k":"Recomendación","t":"Se Recomienda: A los comités de área constituir su comité de finanzas como lo Recomienda el Manual de Servicio.","p":14},{"c":"Finanzas","a":1987,"k":"Recomendación","t":"Recomendamos: Al comité de finanzas y a la OSG canalizar los fondos de la Corporación en entidades bancarias o corporaciones que tengan amplio respaldo oficial. Con esta Recomendación buscamos el máximo de seguridad para las reservas de nuestra amada comunidad.","p":14},{"c":"Finanzas","a":1987,"k":"Recomendación","t":"Se Recomienda: a los grupos de todas las áreas no recurrir a rifas o fiestas para el mantenimiento del grupo. Que los R.S.G. destaquen la necesidad del auto mantenimiento.","p":14},{"c":"Finanzas","a":1989,"k":"Recomendación","t":"Se Recomienda: la necesidad de motivar la aplicación del Plan 60-30-10 para que sea incluido dentro del presupuesto del grupo y sirva para el sostenimiento de la oficina de inter grupos, comités de área y OSG.","p":14},{"c":"Finanzas","a":1990,"k":"Recomendación","t":"Se Recomienda: a la OSG publicar el plegable de auto mantenimiento con la explicación del Plan 60-30-10, haciendo claridad que dentro de los gastos básicos del grupo además del arriendo, los gastos de cafetería y servicios, se encuentran también los aportes a la OSG, la oficina de inter grupos y el comité de área. Si después de cubrir los gastos queda algún excedente se le aplica el Plan 60-30-10.","p":14},{"c":"Finanzas","a":1991,"k":"Recomendación","t":"Se Recomienda: como estrategia adicional para captar más fondos para la OSG que en las reuniones de aniversario de los miembros de A.A. el 50% de las contribuciones que se recolecten en cada una de éstas, se envíe como aporte a la OSG.","p":14},{"c":"Finanzas","a":1992,"k":"Recomendación","t":"Se Recomienda: en la aplicación del Plan 60-30-10, en referencia con los excedentes de los grupos, cuando no exista oficina intergrupal, se aplique en la siguiente forma: 70% para la OSG y el 30% para el área sede.","p":14},{"c":"Finanzas","a":1993,"k":"Recomendación","t":"Se Recomienda: Nuevamente la prudente reserva para los grupos de dos (2) meses, para los inter grupos y comités de área seis (6), y para la OSG de un (1) año.","p":14},{"c":"Finanzas","a":2000,"k":"Recomendación","t":"Se Recomienda: Que todos los centros de servicio del país apliquen la mayor diligencia posible para que todos los tesoreros o personas encargadas de hacer giros de dineros a la Corporación Nacional de Servicios de A.A. (O.S.G.), especifiquen en cada caso el origen o razón de cada cuenta en la consignación, con el objetivo de que la contabilidad de la Corporación esté completamente actualizada. Si al término del ejercicio contable tenemos saldos a favor por consignaciones efectuadas por algún cuerpo de servicio que no la identificó en su momento, esta oficina tiene plena facultad para hacer su apropiación.","p":14},{"c":"Finanzas","a":2003,"k":"Recomendación","t":"Se Recomienda: que en todos los eventos masivos y de grupos, foros, congresos, talleres, etc., haya un taller sobre auto mantenimiento, valor espiritual del dinero.","p":15},{"c":"Finanzas","a":2004,"k":"Moción","t":"Moción: Que el balance de cierre sea acompañado de las notas explicativas o aclaratorias necesarias para su comprensión contable.","p":15},{"c":"Finanzas","a":2004,"k":"Moción","t":"Moción: la Conferencia aprobar anualmente el balance general de la Corporación a 31 de diciembre del año anterior, y el presupuesto del año vigente.","p":15},{"c":"Finanzas","a":2005,"k":"Recomendación","t":"Se Recomienda: que los excedentes de los eventos zonales como congresos, foros y encuentros de servidores, sean distribuidos así: El 60% para la OSG El 20% para el próximo evento El 20 % para el área sede. (Esta Recomendación, reemplaza la Recomendación de 1992 (60-30-10)).","p":15},{"c":"Finanzas","a":2007,"k":"Recomendación","t":"Se Recomienda: a las áreas desarrollar talleres en sus respectivos comités, distritos y grupos, basados en el plegable “El Automantenimiento en AA”","p":15},{"c":"Finanzas","a":2007,"k":"Sugerencia","t":"Sugerencia: Que las áreas utilicen el correo electrónico para comunicarnos en doble vía con la OSG, con el fin de ahorrar lo que se invierte actualmente en correo certificado.","p":15},{"c":"Finanzas","a":2008,"k":"Recomendación","t":"Recomendamos: modificar la Recomendación de 1997, de la siguiente manera: “Se Recomienda que las contribuciones voluntarias de los miembros de AA. Con destino a la OSG, tengan como máximo doce salarios mínimos legales mensuales por año.","p":15},{"c":"Finanzas","a":2009,"k":"Sugerencia","t":"Se sugiere: Que los informes estadísticos sobre ventas de literatura se presenten tanto en pesos como en unidades vendidas.","p":15},{"c":"Finanzas","a":2010,"k":"Recomendación","t":"Se Recomienda: que los excedentes de los eventos nacionales, sean distribuidos así: 60% para la Corporación Nacional De Servicios Generales de AA 20% para el próximo evento de similar característica. 10% Región. 10% para el área que la realice.","p":15},{"c":"Finanzas","a":2010,"k":"Recomendación","t":"Se Recomienda: incluir en todas las publicaciones del año de la Revista El Mensaje y el Boletín Nacional, un artículo de motivación sobre la necesidad e importancia del Automantenimiento para nuestra Comunidad.","p":15},{"c":"Finanzas","a":2011,"k":"Recomendación","t":"Se Recomienda: que se elabore un afiche que contenga los diferentes planes de Automantenimiento, para que sea ubicado en un lugar visible de los grupos, Inter grupos y comités de área y sea una herramienta de motivación de nuestra responsabilidad frente al Automantenimiento.","p":15},{"c":"Finanzas","a":2012,"k":"Moción","t":"Moción: Que la Semana de la Gratitud consistente en que los dineros recaudados en los grupos, por concepto de Séptima Tradición, en la última semana del mes de noviembre de cada año, sean enviados en su totalidad a la OSG.","p":15},{"c":"Finanzas","a":2013,"k":"Sugerencia","t":"Se sugiere: al comité de finanzas de la junta de servicios generales presentar en el informe anual un cuadro comparativo de las ventas de literatura de los últimos tres años por título. Se le sugirió al comité de finanzas de la junta de servicios generales presentar los estados financieros del año anterior en el mes de marzo del año siguiente para evitar correcciones.","p":15},{"c":"Finanzas","a":2013,"k":"Sugerencia","t":"Sugerencia: Presentar en los estados financieros el análisis los indicadores financieros con el objeto que toda la comunidad entienda la situación de nuestra corporación.","p":16},{"c":"Finanzas","a":2014,"k":"Sugerencia","t":"Sugerencia: Que los estados de Resultados se elaboren con otra presentación, para que así, coincidan con el presupuesto y sean más entendibles por la conciencia de grupo. Esta Sugerencia fue establecida con la presencia de la Contadora y el Revisor Fiscal de la Corporación de la OSG.","p":16},{"c":"Finanzas","a":2015,"k":"Recomendación","t":"Se Recomienda: cambiar el lenguaje y las bases sugeridas para liquidar el Plan Aniversario Miembro y el Plan Aniversario Grupo o porcentaje sobre el salario mínimo así: Plan Aniversario Miembro, PAM; el 1% sobre el salario mínimo legal mensual vigente por cada año de sobriedad, o lo que decida el miembro de acuerdo a su capacidad económica. Plan Aniversario Grupo, PAG; el 7% sobre el salario mínimo legal mensual vigente cada que el grupo cumpla aniversario, o lo que decida el grupo de acuerdo a su capacidad económica.","p":16},{"c":"Finanzas","a":2015,"k":"Sugerencia","t":"Sugerencia: Que el balance general y el estado de beneficios de la Corporación Nacional de Servicios Generales de junio y diciembre sean enviados a los integrantes del Comité de Finanzas de la Conferencia y además sean publicados en el boletín de los meses de marzo y agosto de cada año. (Acción Recomendable del año 1995).","p":16},{"c":"Finanzas","a":2017,"k":"Recomendación","t":"Se Recomienda: Actualizar los saldos de la prudente reserva capitalizando los intereses que ésta produzca, adicionando el 2.5 % de los excedentes de las ventas de literatura.","p":16},{"c":"Finanzas","a":2017,"k":"Moción","t":"Moción de recordación: Que el Comité de Finanzas y presupuesto de los Custodios, cada que se reúnan, le envié los balances al respectivo Comité de Conferencia.","p":16},{"c":"Finanzas","a":2019,"k":"Moción","t":"Moción de piso","p":16},{"c":"Finanzas","a":2019,"k":"Recomendación","t":"Se Recomienda que la Recomendación del año 2005 que dice: “Se Recomienda: que los excedentes de los eventos Zonales como Congresos, foros y encuentros de servidores, sean distribuidos así: El 60% para la OSG, El 20 % Para el próximo evento, El 20% para el área sede” Por el siguiente texto:","p":16},{"c":"Finanzas","a":2019,"k":"Recomendación","t":"Se Recomienda: que los excedentes de los eventos Regionales como Congresos, foros y encuentros de servidores, sean distribuidos así: El 60% para la Corporación Nacional de AA, El 20 % Para el próximo evento, El 20% para el área sede. 2020Se Recomienda: Crear Reserva de eventos nacionales: a partir del excedente actual; se incrementará sumándole el 10% de los excedentes de cada evento nacional. Dicha reserva se protegerá, teniendo en cuenta que esta no hace parte de los ingresos de los eventos. Que el Plan de Auto mantenimiento “excedentes nacionales” quedaría 70% para la corporación, 10% para el fondo de reserva de eventos nacionales, 10% para la Región sede y 10 % para el Área sede. El tope del fondo de eventos nacionales será de70 SMMLV y cuando se obtenga este tope el 10% de excedente pasará a la corporación.","p":16},{"c":"Finanzas","a":2022,"k":"Nota","t":"FINANZAS Fue aprobado el presupuesto para el año 2022. Fue aprobado la distribución de excedentes del año 2021. (Ver cuadro en la pág. 122 de informe final de la 58 CSG)","p":17},{"c":"Finanzas","a":2022,"k":"Moción","t":"Moción DE PISO Que en la plenaria deliberativa de aprobación de balance general del año anterior y presupuesto del año en curso estén presente el contador y revisor fiscal.","p":17},{"c":"Finanzas","a":2022,"k":"Moción","t":"Moción DE RECORDACIÓN AÑO 2004: Se Recomienda que el balance de cierre sea acompañado de las notas explicativas o aclaratorias necesarias para su comprensión contable.","p":17},{"c":"Finanzas","a":2022,"k":"Moción","t":"Moción DE RECORDACIÓN AÑO 1976: Se Recomienda a los grupos y oficina de servicio local que se abstengan de publicar en las carteleras los nombres de los compañeros que hagan aportes voluntarios para Alcohólicos Anónimos.","p":17},{"c":"Finanzas","a":2023,"k":"Nota","t":"Reunido el Comité y con la presencia de la Contadora de la corporación, el Revisor Fiscal, y los Coordinadores de los Comités de Finanzas de la Junta de Servicios Generales y la Entidad Operativa de Servicios Generales, se analizaron y revisaron los estados financieros correspondientes al período fiscal 2022 al igual que el presupuesto para el año 2023. Aclaradas las inquietudes, despejados los interrogantes y teniendo en cuenta el dictamen contable presentado por Revisor Fiscal el Comité manifiesta que se encuentran ajustados a las operaciones de la comunidad para el cabal cumplimiento de su objetivo. Por lo expuesto anteriormente se da por aprobado el estado financiero 2022. Al igual que el presupuesto para el año 2023.","p":17},{"c":"Finanzas","a":2023,"k":"Recomendación","t":"Se Recomienda que se anule la Acción Recomendable del Comité de Finanzas aprobado en la Conferencia 58, que dice: “Que en la Plenaria deliberativa de aprobación del balance del año anterior y presupuesto del año en curso estén presente el Contador y Revisor Fiscal”.","p":17},{"c":"Finanzas","a":2023,"k":"Moción","t":"Moción de Recordación: En 1984 se recomendó que la Semana de la Gratitud que se celebra en el mes de noviembre, mes de las Tradiciones, sea promovida por parte de la OSG y Comités de Área con la suficiente anticipación y por medio de los cuerpos de servicio a través de boletines y todos los medios posibles de difusión a los grupos.","p":17},{"c":"Finanzas","a":2024,"k":"Moción","t":"Moción de Recordación 2017: que el Comité de Finanzas y Presupuesto de los Custodios, cada vez que se reúna, le envíe los balances al respectivo Comité de Conferencia.","p":17},{"c":"Finanzas","a":2025,"k":"Sugerencia","t":"Sugerencia: actualizar la guía de eventos nacionales, que los proveedores contratados cumplan con las normas legales vigentes y la corporación exija las pólizas de cumplimiento.","p":17},{"c":"Finanzas","a":2025,"k":"Recomendación","t":"Se recomienda: a la JSG que después de aprobar el presupuesto para los eventos nacionales se presente dicho prepuesto al Comité de Finanzas de la Conferencia para su conocimiento.","p":17},{"c":"Finanzas","a":2025,"k":"Moción","t":"Moción de recordación año 2017: Que el comité de finanzas y presupuesto de los custodios, cada que se reúnan, le envié los balances al comité respectivo de conferencia.","p":17},{"c":"Finanzas","a":2026,"k":"Moción","t":"Moción de recordación: “Se Recomienda: que los excedentes de los eventos Zonales como Congresos, Foros y Encuentros de Servidores, sean distribuidos así: El 60% para la OSG, El 20 % Para el próximo evento, El 20% para el área sede” se cambie por el siguiente texto: “Se Recomienda: que los excedentes de los eventos Regionales como Congresos, Foros y Encuentros de Servidores, sean distribuidos así: El 60% para la Corporación Nacional de AA, El 20 % para el próximo evento, El 20% para el área sede”.","p":17},{"c":"Finanzas","a":2026,"k":"Moción","t":"Moción de recordación: Realizar recordación a todos los grupos y miembros de la Recomendación del año 1973 que dice: “Se sugiere a todos los miembros de AA un aporte voluntario mensual con destino a la OSG. La forma de recaudar este aporte queda a criterio de los Grupos” Nota: Los miembros del Comité de Finanzas de La Conferencia se reunieron con el contador de la Corporación, su Auxiliar Contable, el Director No Custodio del Comité de Finanzas de la Entidad Operativa de Servicios Generales, Custodio de Servicios Generales y el Gerente encargado de la Corporación y se analizaron, revisaron y fueron aclaradas las inquietudes sobre la distribución de los excedentes, el Balance y Estado de Resultados a Diciembre 2025 y Presupuesto para el año 2026, considerando que está acorde con las normas Contables y el objetivo de la Comunidad.","p":18},{"c":"Cooperación con la Comunidad Profesional","a":1992,"k":"Recomendación","t":"Se Recomienda: a las áreas que, por intermedio de sus comités de CCP, inicien el plan “Apadrinemos un Profesional” mediante el envío del boletín “Acerca de A.A.” y la literatura apropiada.","p":18},{"c":"Cooperación con la Comunidad Profesional","a":1993,"k":"Moción","t":"Moción: a los comités de área a través de su CCP, ejecutar efectivamente el plan de apadrinamiento a un profesional.","p":18},{"c":"Cooperación con la Comunidad Profesional","a":2000,"k":"Recomendación","t":"Se Recomienda: a las áreas enviar a la OSG informes concernientes a las experiencias de trabajo del comité Trabajando con Otros CTO, (IP, TI- CCP), con el objetivo de conformar un banco de datos.","p":18},{"c":"Cooperación con la Comunidad Profesional","a":2000,"k":"Recomendación","t":"Se Recomienda: Que se edite una carpeta de presentación para trabajos de CCP, que pueda ser adaptada por CTO o demás comités.","p":18},{"c":"Cooperación con la Comunidad Profesional","a":2001,"k":"Recomendación","t":"Se Recomienda: formar un banco de datos en el Comité Trabajando con Otros CTO alimentado por los CCP de las áreas, renovándolo por lo menos cada año.","p":18},{"c":"Cooperación con la Comunidad Profesional","a":2004,"k":"Recomendación","t":"Recomendamos: Que los custodios zonales, delegados y coordinadores de área sean responsables de la conformación y puesta en funcionamiento de los C.T.O. en las áreas.","p":18},{"c":"Cooperación con la Comunidad Profesional","a":2004,"k":"Recomendación","t":"Recomendamos: a los Comités de CCP de las áreas, que después de cada información al público se le dé continuidad con algún trabajo de CCP.","p":18},{"c":"Cooperación con la Comunidad Profesional","a":2006,"k":"Recomendación","t":"Se Recomienda: Que la Junta de Custodios apoye a los CCP de las áreas en la realización anual de un Encuentro de Área de Amigos Profesionales de AA.","p":18},{"c":"Cooperación con la Comunidad Profesional","a":2010,"k":"Recomendación","t":"Se Recomienda: Elaborar una guía práctica para los encuentros de profesionales en el territorio nacional. (Anexamos modelo) Esta guía estará dividida en tres momentos: ANTES Los temas deben ser elegidos acordes con el encuentro y con anticipación (recordar que no es una IP.) En lo posible se debe contactar a los oradores no alcohólicos con suficiente anterioridad, igual que a los suplentes. Los oradores no alcohólicos deben ser personas que ya tengan un amplio conocimiento de la comunidad y de la enfermedad del alcoholismo, además de demostrar aprecio por AA.","p":18},{"c":"Cooperación con la Comunidad Profesional","a":2010,"k":"Sugerencia","t":"Se sugiere no atiborrar de temas la programación y dejar suficiente espacio libre para que los profesionales puedan compartir entre si y ante todo con los miembros de la comunidad. A los profesionales que también acudirán como asistentes se les debe notificar con una carta por los menos con un mes de anticipación y llamarlos a confirmar con unos días de anticipación. El lugar del evento es preferible que sea un lugar campestre y tranquilo. Los asistentes deben ser la mayoría no alcohólicos y una minoría de miembros de la comunidad que lleven suficiente tiempo de sobriedad. - La inscripción y los gastos que impliquen la asistencia de los profesionales debe ser patrocinada por miembros de la comunidad, grupos distritos o áreas. En el plegable de la programación se debe tener en cuenta que a los oradores profesionales se les debe colocar el nombre completo y profesión, ej.: el doctor Pepito Pérez Rodríguez –psicólogo especialista en sicología social de la Universidad del Valle. Esto debido a que la comunidad no debe obligarlo al anonimato, pues este rige para los miembros de ella y no para otros. DURANTE Debe haber un comité encargado del recibimiento y ubicación de los profesionales. Estas apersonas deben estar puntualmente a la hora acordada en la invitación a los Profesionales. Al inicio hacer una presentación breve de los profesionales donde digan su nombre, Profesión y expectativas con el evento y al final una evaluación donde expresen su parecer con el mismo. Se considera importante que en los espacios libres se comparta entre miembros de AA y los profesionales; pues es allí donde los profesionales mejor pueden conocer a la comunidad.","p":19},{"c":"Cooperación con la Comunidad Profesional","a":2010,"k":"Sugerencia","t":"Se sugiere que el último punto de la programación sea una plenaria donde los profesionales participen con preguntas o sus aportes profesionales. Se comprometen. La alimentación debe ser de excelente calidad y presentación. Importante tener claro que se procura un compartir de saberes entre miembros de la comunidad y los profesionales. No preocuparse por convertirlos en colaboradores inmediatos y bajo presión. Se ha demostrado que cuando un profesional se enamora de la Comunidad; él mismo sugiere formas de cooperación. DESPUÉS Los encargados del CCP de área deben enviar por escrito a la OSG el informe de lo que fue el evento, acompañado de la información para la base de datos de los profesionales. El comité encargado de la realización debe hacer una reunión para evaluar el evento, con el propósito de mejorar en próximas oportunidades. Los encargados del CCP del área deben ocuparse de que le llegue el boletín a todos los profesionales que estuvieron en el evento. A estos profesionales se les debe seguir apadrinando con literatura de la comunidad e invitándolos a otros eventos, tales como aniversarios de miembros y de grupos, para que sigan teniendo un mayor acercamiento y conocimiento de la Comunidad.","p":19},{"c":"Cooperación con la Comunidad Profesional","a":2010,"k":"Sugerencia","t":"Sugerencia: Que los coordinadores de Instituciones correccionales de cada área de su respectiva región envíen sus correos electrónicos a la secretaría permanente y comuniquen a qué área y región pertenecen, para hacer una base de datos y así tener una buena comunicación entre la J de C, la OSG, los grupos y el coordinador de comité de instituciones correccionales de la conferencia.","p":19},{"c":"Cooperación con la Comunidad Profesional","a":2011,"k":"Moción","t":"Moción: recordar la Recomendación del año 2000 Conferencia 36: “Se Recomienda a las áreas enviar a la OSG informes concernientes a las experiencias de trabajo del Comité Trabajando con Otros (CTO, IP, TI, CCP), con el objetivo de conformar un banco de datos.”","p":20},{"c":"Cooperación con la Comunidad Profesional","a":2014,"k":"Sugerencia","t":"Sugerencia: a todos los entes de servicio de la estructura nacional hacer uso de todo el material aprobado por la Conferencia y por la Junta para hacer CCP. 1. Libro de trabajo de CCP en instituciones. 2. Folletos relacionados con este servicio. 3. El documento de guías para cooperación institucional con entidades gubernamentales.","p":20},{"c":"Cooperación con la Comunidad Profesional","a":2015,"k":"Sugerencia","t":"Sugerencia: A todos los entes de servicio de la estructura, poner en práctica el Plan Nacional de Fortalecimiento, teniendo en cuenta el Plan de Acción para el fortalecimiento de la presencia de Alcohólicos Anónimos en la sociedad. Tener en cuenta que profesional no es solamente aquel que tiene un título profesional, sino cualquier persona por la labor que realice tenga contacto con la comunidad.","p":20},{"c":"Cooperación con la Comunidad Profesional","a":2017,"k":"Recomendación","t":"Se Recomienda: que el CCP de la Junta de Servicios Generales haga contactos a un alto nivel con las instituciones gubernamentales y privadas.","p":20},{"c":"Cooperación con la Comunidad Profesional","a":2019,"k":"Sugerencia","t":"Sugerencia: Que la declaración hecha por el Custodio Clase A de la Junta de Servicios Generales de Estados Unidos George E. Vaillant, que dice “la unicidad de propósito es esencial para el tratamiento eficaz del alcoholismo. El motivo para tener tal exagerado enfoque es el de superar la negación. La negación asociada con el alcoholismo es astuta, desconcertante y poderosa y afecta al paciente, a quien lo ayuda y a la comunidad. A menos que el alcoholismo se mantenga incesantemente en primer plano, otros asuntos usurparan la atención de todos”. Aparezca en los boletines a profesionales y toda la información que tenga que ver con el trabajo de CCP.","p":20},{"c":"Cooperación con la Comunidad Profesional","a":2020,"k":"Moción","t":"Moción de Recordación: Recordar a los grupos que elijan su representante de CCP, como se ubica este servicio en la estructura del grupo, para que ellos sean parte importante del fortalecimiento de los comités de distrito y área.","p":20},{"c":"Cooperación con la Comunidad Profesional","a":2024,"k":"Moción","t":"Moción de recordación: Se solicita a la Junta de Servicios Generales atender lo sugerido por la acción Recomendable del Comité de Cooperación con la comunidad profesional e instituciones de tratamiento del año 2017 para establecer contactos de alto nivel con las instituciones gubernamentales y privadas.","p":20},{"c":"Cooperación con la Comunidad Profesional","a":2025,"k":"Recomendación","t":"Se recomienda: que la JSG realice videos que incluyan lengua de señas y audios informativos de los tres comités que trabajan con la comunidad no AA: IP, CCP e IT con apoyo del Departamento de Comunicaciones y Tecnología de la OSG.","p":20},{"c":"Cooperación con la Comunidad Profesional","a":2025,"k":"Recomendación","t":"Se recomienda: a la JSG que, con el fin de mejorar y fortalecer el trabajo del Comité “Trabajando con Otros”, se lleve a cabo la revisión, edición y distribución de un nuevo manual impreso para el CTO. Este manual debe integrar la información contenida en el folleto CTO, en el que se explica cómo los tres comités se coordinan y colaboran para lograr sus objetivos comunes. El propósito es proporcionar a los grupos, incluso con pocos servidores, una herramienta clara y accesible para comprender el funcionamiento y la importancia de estos comités en su estructura y labor.","p":20},{"c":"Información al Público","a":1977,"k":"Recomendación","t":"Se Recomienda: Que al dar información por la radio acerca de A.A., no se dé al final del programa el número de teléfonos individuales o comerciales. Lo indicado es dar los números de las oficinas locales o de los grupos de A.A. Queremos hacer resaltar la importancia que tiene identificar el nombre del grupo o de la oficina local de A.A. cuando se contesta por teléfono.","p":21},{"c":"Información al Público","a":1977,"k":"Recomendación","t":"Se Recomienda Insistir en que toda la información al público se haga a través de los comités de información, así sean constituidos por un grupo. Es lógico que en los lugares donde existen intergrupos o comités de servicios generales corresponde a estas entidades constituir estos comités de I.P.","p":21},{"c":"Información al Público","a":1980,"k":"Recomendación","t":"Se Recomienda: a los intergrupos, comités de servicio o grupos donde haya Comités de IP, se asigne una partida para estas actividades.","p":21},{"c":"Información al Público","a":1980,"k":"Recomendación","t":"Se Recomienda: al Comité de IP de la Corporación buscar un mayor acercamiento y motivación a los periodistas, para evitar tergiversaciones y malos entendidos en cuanto a la imagen de AA.","p":21},{"c":"Información al Público","a":1982,"k":"Recomendación","t":"Se Recomienda: a aquellos miembros de AA que trabajan en el campo del alcoholismo que se hagan más conscientes de las tradiciones para lograr la mayor claridad en el principio de “Cooperación sí, afiliación no”.","p":21},{"c":"Información al Público","a":1982,"k":"Recomendación","t":"Se Recomienda: que los grupos de AA que se reúnan en instituciones donde se da tratamiento a los alcohólicos se protejan con la Tradición Siete; si no se nos acepta dinero para el pago de arrendamiento, los grupos deben contribuir en alguna otra forma, y que los empleados de AA pagados por la institución no coordinen esas reuniones ni esos grupos.","p":21},{"c":"Información al Público","a":1982,"k":"Recomendación","t":"Se Recomienda: reiterar a los miembros de AA interesados en informar al público, que se abstengan de narrar historiales trágicos o situaciones de permanentes borracheras para que el público no vaya a confundir el alcoholismo con maldad o nuestra enfermedad con solamente borracheras.","p":21},{"c":"Información al Público","a":1983,"k":"Recomendación","t":"Se Recomienda: A.A. y que nuestra comunidad A los encargados de información al público recalcar que A.A. no tiene opiniones sobre las causas del alcoholismo o su prevención, sino sobre el programa de recuperación de no es una sociedad de temperancia.","p":21},{"c":"Información al Público","a":1991,"k":"Recomendación","t":"Se Recomienda: extender las labores de información pública al sector rural.","p":21},{"c":"Información al Público","a":1999,"k":"Recomendación","t":"Se Recomienda: al comité de área e intergrupos, que el día 10 de junio de cada año, se celebre en Colombia, la fundación de Alcohólicos Anónimos, sugiriendo que durante el día se dé información permanente a la comunidad en general, utilizando los medios masivos de comunicación para su divulgación.","p":21},{"c":"Información al Público","a":2001,"k":"Recomendación","t":"Se Recomienda: que la Junta de Servicios Generales, las zonas* y los comités de área conformen los Comités Trabajando con Otros “CTO” *(Zona hoy equivale a Región en el nuevo manual edición 2014)2002","p":21},{"c":"Información al Público","a":2001,"k":"Recomendación","t":"Se Recomienda: iniciar y/o reforzar en los grupos, distritos y comités de área, los talleres de capacitación sobre cómo hacer información al público, utilizando las guías recomendadas por la Conferencia.","p":22},{"c":"Información al Público","a":2004,"k":"Recomendación","t":"Se Recomienda: Unificar el uso del nombre, del símbolo de AA y de todo aquello que tenga que ver con nuestra Comunidad, tanto para el uso interno como para el uso externo, esto debe tenerse en cuenta en los avisos de grupo, papelería, etc. a todos los niveles de la estructura de Servicios Generales, desde el grupo hasta la OSG.","p":22},{"c":"Información al Público","a":2006,"k":"Recomendación","t":"Se Recomienda: a los comités de área, utilizar los canales locales y regionales (TV-cables, parabólicas, etc.), para transmitir los comerciales de AA.","p":22},{"c":"Información al Público","a":2008,"k":"Recomendación","t":"Se Recomienda: homogenizar los avisos de IP de acuerdo a los parámetros señalados en el plegable de la imagen corporativa en cuanto al color y demás indicaciones que es el color azul.","p":22},{"c":"Información al Público","a":2009,"k":"Recomendación","t":"Se Recomienda: Que todos los cuerpos de servicio general acaten la Recomendación respecto a la utilización de la Imagen Corporativa en comunicados, revistas, boletines, blogs, páginas web, correos, avisos, tarjetas de grupo, afiches de eventos, etc. (Manual de Servicios, Tamaño Carta M83 y 84 – Tamaño Media C 117 y 118).","p":22},{"c":"Información al Público","a":2009,"k":"Recomendación","t":"Se Recomienda: A los grupos, acatar la resolución del Ministerio de Protección Social en lo referente a la prohibición de fumar en recintos cerrados. 2010Sugerencia: actualizar los anuncios de servicio público para la radio y la televisión y actualizar el código civil* ante la comisión Nacional de televisión – CNTV* que se permita La difusión de dichos anuncios y renovarla cada vez que sea necesario.","p":22},{"c":"Información al Público","a":2009,"k":"Recomendación","t":"Se Recomienda: Que el Comité de IP de la Junta realice cada 3 años una encuesta de los miembros de AA, con el fin de conocer el perfil actual de los alcohólicos anónimos en Colombia.","p":22},{"c":"Información al Público","a":2011,"k":"Moción","t":"Moción: sugerimos que por ningún motivo se hagan fotocopias de nuestra literatura impresa. *En la actualidad, los términos correctos son: Código Cívico y Autoridad Nacional de Televisión - ANTV)Se recomendó: que, en aras de preservar nuestro anonimato personal en el desarrollo oficial de nuestras reuniones de grupo, área, conferencia, foros, congresos y convenciones, no se tomen fotos ni se hagan filmaciones. Que, en aras de preservar nuestro anonimato personal en la realización de nuestros eventos, todos los elementos de uso personal que el miembro vaya a utilizar, tales como: escarapelas, camisetas, botones y otros no aparezca ninguna mención, ni logo ni nombre de AA. A la comunidad de AA de Colombia en general, que se abstenga de publicar en las páginas sociales de Internet fotos, documentos escritos y videos que puedan violar nuestro manto protector de anonimato.","p":22},{"c":"Información al Público","a":2012,"k":"Recomendación","t":"Se Recomienda: Aprobar las guías de I.P. presentadas por el comité transitorio para su aplicación a nivel nacional.","p":22},{"c":"Información al Público","a":2012,"k":"Moción","t":"Moción: sugerimos a los grupos reactivar el Comité de Bienvenida o Recepción para que se le haga acompañamiento al nuevo. Esto ajustándonos a las nuevas guías.","p":22},{"c":"Información al Público","a":2014,"k":"Recomendación","t":"Recomendación: Que en una misma publicación se incluyan los manuales de IP, CCP, IT e IC","p":22},{"c":"Información al Público","a":2016,"k":"Recomendación","t":"Recomendación: Incluir la siguiente frase: “Y además el Estado colombiano ha reconocido el alcoholismo como un problema de salud pública” en la diapositiva de la Guía Nacional de IP donde las autoridades médicas reconocen el alcoholismo como una enfermedad.","p":23},{"c":"Información al Público","a":2016,"k":"Moción","t":"Moción de recordación Se Recomienda que, a todos los niveles de servicio de la Comunidad, se pongan en práctica las siguientes estrategias para proteger el anonimato en las redes sociales. 1. Estudiar las recomendaciones dadas en el libro de trabajo de I.P Pág. 54, donde se hace referencia específica al anonimato en redes sociales. 2. Que en todos los eventos se haga énfasis sobre el anonimato en redes sociales. 3. Que mediante el apadrinamiento se oriente a los recién llegados sobre la importancia del anonimato en las redes sociales.","p":23},{"c":"Información al Público","a":2019,"k":"Moción","t":"Moción de recordación. Año 2010, Se Recomienda que el Comité de Información Pública de la Junta, realice cada tres años una encuesta en los miembros de AA, con el fin de conocer el perfil actual de los AA en Colombia.","p":23},{"c":"Información al Público","a":2020,"k":"Moción","t":"Moción de Recordación. En la conferencia 48 del año 2012 se dijo: “sugerimos a los grupos reactivar el comité de bienvenida o recepción para que se haga acompañamiento al nuevo, esto ajustándonos a las nuevas guías”.","p":23},{"c":"Información al Público","a":2021,"k":"Recomendación","t":"Se Recomienda a la Junta de Servicios Generales que para el año 2022, se elabore una presentación adicional de IP dirigida al público juvenil y se actualice la guía vigente","p":23},{"c":"Información al Público","a":2021,"k":"Recomendación","t":"Se Recomienda a la Junta de Servicios Generales que a partir del año 2021 se cree un link para acceso directo a reuniones virtuales de AA en la página principal de la Corporación.","p":23},{"c":"Información al Público","a":2022,"k":"Nota","t":"INFORME Y CARTA CONSTITUTIVA Se Recomienda: Que, en el afiche de la Reunión Anual de la Conferencia de Servicios Generales, predomine el color tradicional de A.A. y que el logo que aparezca sea de acuerdo con la imagen correspondiente según el Manual de Imagen Corporativa.","p":23},{"c":"Información al Público","a":2022,"k":"Recomendación","t":"Se Recomienda: Omitir en el Manual de Servicios, en la página (M113), en el párrafo que dice: “Debido a este requisito, originalmente los custodios de servicios generales residían en Medellín y su área metropolitana, y a veces se conocían como “custodios dentro de la ciudad”; ahora que hay posibilidad de comunicarse más rápidamente y con mayor eficacia por teléfono, así como por correo y medios electrónicos, las personas que no son residentes en Medellín y sus alrededores también pueden ocupar estos servicios” Y transcribir el párrafo del artículo 8, página (M176) de los estatutos que dice: “El custodio de servicios generales será del área correspondiente a Medellín o sus áreas vecinas”","p":23},{"c":"Información al Público","a":2022,"k":"Moción","t":"Moción DE PISO Que la Junta de Servicios Generales revise los Manuales de Imagen Corporativa y estos coincidan con lo que aparece en el Manual de Servicios PAG. M129 – M130. Aprobado","p":23},{"c":"Información al Público","a":2022,"k":"Moción","t":"Moción DE PISO Que todos los afiches pendones y volantes de los eventos tengan el logo de Alcohólicos Anónimos de acuerdo con la imagen corporativa según el Manual de Servicios PAG. M130. Aprobado.","p":23},{"c":"Información al Público","a":2024,"k":"Moción","t":"Moción de recordación 2011: que, en aras de preservar nuestro anonimato personal en el desarrollo oficial de nuestras reuniones de Grupo, de Área, Conferencia, Foros, Congresos y Convenciones no se tomen fotos ni se hagan filmaciones. Que, en aras de preservar nuestro anonimato personal en la realización de nuestros eventos, todos los elementos de uso personal que el miembro vaya a utilizar, tales como: escarapelas, camisetas, botones y otros no aparezca ninguna mención, ni logo de AA. A la comunidad de AA Colombia en general que se abstenga de publicar en las páginas sociales de internet fotos, documentos, escritos y videos que puedan violar nuestro manto protector de anonimato.","p":24},{"c":"Información al Público","a":2025,"k":"Recomendación","t":"Se recomienda: a la Junta de Servíos Generales ampliar la difusión del mensaje de AA para alcanzar a más personas que puedan necesitar ayuda o información sobre el alcoholismo, utilizando redes sociales y otros medios digitales, respetando nuestros 36 principios. Sólo con material producido por el Departamento de Comunicaciones y Tecnología de la OSG.","p":24},{"c":"Información al Público","a":2025,"k":"Moción","t":"Moción de recordación: Se recuerda a la JSG el cumplimiento de las Acciones Recomendables: años 2004 y 2009 del Comité de IP, en cuanto al uso de la Imagen Corporativa a todo nivel de la Estructura de Servicio.","p":24},{"c":"Información al Público","a":2026,"k":"Recomendación","t":"Se recomienda a la JSG con el apoyo y asesoría del Departamento de Tecnología y Comunicaciones elaborar un Plan de Acción a mediano y largo plazo para mantener al día o actualizadas las redes sociales de la corporación que actualmente tenemos y abrir aquellas que aún no tenemos en la web y en la página aacolombia.org","p":24},{"c":"Información al Público","a":2026,"k":"Recomendación","t":"Se recomienda a la JSG de Colombia actualizar la Guía Nacional de Información Pública (I.P.) tomando en cuenta las siguientes sugerencias: Pág. # 8: Síntomas. En los puntos adicionar la palabra “Negación”. En la pág. # 19 se propone que se actualice las cifras pasadas por cifras actuales al momento de la estadística (fecha de edición de la guía) referente a la presencia de A.A. en el mundo y en Colombia.","p":24},{"c":"Instituciones","a":1994,"k":"Recomendación","t":"Se Recomienda: La inclusión en los foros, talleres y otras actividades del área, intergrupos y demás entes de servicio, información sobre la manera como puede hacerse el trabajo en centros de tratamiento e instituciones carcelarias.1997","p":24},{"c":"Instituciones","a":1994,"k":"Recomendación","t":"Se Recomienda: que el trabajo en Instituciones carcelarias sea llevado a cabo en lo posible por miembros del mismo sexo, es decir, los hombres a los centros donde están recluidos los hombres y las mujeres donde están recluidas las mujeres.","p":24},{"c":"Instituciones","a":2002,"k":"Recomendación","t":"Se Recomienda: para mantener nuestras buenas relaciones y la buena imagen de Alcohólicos Anónimos, que toda actividad relacionada con los subcomités de Instituciones carcelarias y hospitalarias, se realice a través del comité de área, intergrupos, distritos o grupos y no por miembros de la comunidad, en forma individual.","p":24},{"c":"Instituciones","a":2004,"k":"Moción","t":"Moción: Que las áreas conformen el Comité de Instituciones Carcelarias y Hospitalarias","p":24},{"c":"Instituciones","a":2010,"k":"Sugerencia","t":"Se sugiere: que los coordinadores de instituciones correccionales de cada área de sus respectivas regiones, envíen sus correos electrónicos a la secretaría permanente y comunicar a qué área y región pertenecen para hacer una base de datos y así tener una buena comunicación, entre la Junta de Custodios, la OSG, los Grupos y el Coordinador de intuiciones correccionales de la conferencia.","p":25},{"c":"Instituciones","a":2014,"k":"Sugerencia","t":"Se sugiere: que todas las áreas del país hagan un censo de los grupos carcelarios que existen en la actualidad y además de los lugares donde existen centros penitenciarios, pero no hay grupos de AA. los datos necesarios son: Nombre y ubicación del grupo, Nombre, correo u teléfono del coordinador de dicho grupo. Hecho esto, se enviará la información a la OS","p":25},{"c":"Instituciones","a":2015,"k":"Recomendación","t":"Recomendación: que se haga un banco de literatura en las áreas donde los miembros de la comunidad depositen los libros, folletos y revistas que consideren que pueden donar.","p":25},{"c":"Instituciones","a":2016,"k":"Moción","t":"Moción de Piso: Debido al trabajo que se está haciendo en las cárceles, Se Recomienda que se realicen los talleres de capacitación y estructuración con base en el manual de Instituciones Correccionales en áreas y regiones.","p":25},{"c":"Instituciones","a":2017,"k":"Recomendación","t":"Se Recomienda: Que la OSG, solicite a Estados Unidos el último video llamado ‘Hay una nueva libertad’ y se socialice en las áreas. Para que sirva de instrumento de trabajo en las instituciones carcelarias.","p":25},{"c":"Instituciones","a":2018,"k":"Moción","t":"Moción de recordación: Que el comité de CCP de las áreas, sean más efectivas al contactar a los profesionales, para que el Comité de IP e IT, pueda hacer su correspondiente labor.","p":25},{"c":"Instituciones","a":2018,"k":"Moción","t":"Moción de recordación: Que se recuerde enviar la solicitud a la estructura americana: los videos: “Una Nueva Libertad” que son dos, uno dirigido a los profesionales y otro a los presos.","p":25},{"c":"Instituciones","a":2019,"k":"Moción","t":"Moción de recordación. Que se recuerde enviar la solicitud a la estructura americana los videos ‘una nueva libertad’, una dirigida a los profesionales y otra a los presos.","p":25},{"c":"Instituciones","a":2019,"k":"Sugerencia","t":"Sugerencia. El Comité de Instituciones Correccionales promover que en las cárceles exista un buzón que incluya literatura y un directorio de los grupos del país.","p":25},{"c":"Instituciones","a":2023,"k":"Recomendación","t":"Se Recomienda que la JSG, coloque en marcha la revisión y la actualización de contextos de nuestro actual libro de trabajo de Instituciones Correccionales. Como última actividad de plenaria el domingo en la noche, se deliberó sobre una Moción de Piso, la cual, no fue aprobada.","p":25},{"c":"Instituciones","a":2024,"k":"Moción","t":"Moción de recordación: Se recomienda la inclusión en los foros, talleres y otras actividades de área, intergrupos y demás entes de servicio, información sobre la manera cómo pueden hacerse el trabajo en centro de tratamiento e instituciones carcelarias. Esto fue aprobado en la Conferencia de 1994.","p":25},{"c":"Instituciones","a":2026,"k":"Recomendación","t":"Se recomienda: cambiar el nombre del comité de instituciones correccionales por comité de Instituciones Carcelarias.","p":26},{"c":"Instituciones","a":2026,"k":"Moción","t":"Moción de recordación: Acción Recomendable 2017: “Que la OSG solicite a Estados Unidos que el último video llamado “Hay una nueva libertad” y se socialice en las áreas para que sirva de instrumento de trabajo en las instituciones correccionales.","p":26},{"c":"Literatura","a":1969,"k":"Recomendación","t":"Se Recomienda Por conveniencia para todo el movimiento evitar hacer publicaciones diferentes a las aprobadas por la Conferencia. También se ruega que en la Oración de la Serenidad y los slogans se mantenga la uniformidad de acuerdo con lo sugerido en los boletines.","p":26},{"c":"Literatura","a":1969,"k":"Recomendación","t":"Se Recomienda De manera especial el estudio de los Doce Pasos y las Doce Tradiciones en reuniones cerradas.","p":26},{"c":"Literatura","a":1970,"k":"Recomendación","t":"Se Recomienda Que este comité esté en perfecta concordancia con el Comité de Finanzas.","p":26},{"c":"Literatura","a":1970,"k":"Recomendación","t":"Se Recomienda Que cuando la revista éste en circulación, éste boletín pasará a ser un vehículo de información no sólo de la OSG, sino también de los grupos en general, sobre sus actividades y, su distribución deberá ser con costos fijados por la OSG.","p":26},{"c":"Literatura","a":1970,"k":"Recomendación","t":"Se Recomienda Comprometernos para que la mística por la lectura y aplicación de la literatura sean una realidad, tenemos la absoluta seguridad de que el mensaje de A.A. será más efectivo y la recuperación del alcohólico más firme y por lógica consecuencia, la ayuda a nuestra oficina de servicios más real y efectiva.","p":26},{"c":"Literatura","a":1971,"k":"Recomendación","t":"Se Recomienda Estudiar los folletos “A.A. el Grupo” y “Cómo Comienza A.A. Cómo Crece”, para seguir las Sugerencias y estructurar debidamente los grupos.","p":26},{"c":"Literatura","a":1974,"k":"Recomendación","t":"Se Recomienda Que para lograr una mayor difusión de la revista “A.A. el mensaje”, los encargados de la literatura en cada uno de los grupos, fomenten las suscripciones anuales de dicha publicación, teniendo presente las recomendaciones del folleto “El Grupo de A.A.” respecto al representante del Grapevine.","p":26},{"c":"Literatura","a":1978,"k":"Recomendación","t":"Se Recomienda: Que la Conferencia reitere recomendaciones anteriores a los miembros y grupos de AA para que no editen tarjetas personales, almanaques, postales que lleven el nombre de AA con las letras AA; ni mezclar el nombre de nuestra comunidad con oraciones o frases que no correspondan a nuestra literatura.","p":26},{"c":"Literatura","a":1981,"k":"Recomendación","t":"Se Recomienda: Que en lo posible la OSG continúe prefiriendo las oficinas de intergrupos en las ciudades donde existan para la distribución de la literatura.","p":26},{"c":"Literatura","a":1982,"k":"Recomendación","t":"Se Recomienda: Nuevamente a los grupos y miembros de AA que en los membretes y remites de los sobres NO utilicen las palabras “Alcohólicos Anónimos “ni tampoco las iniciales de A.A.","p":26},{"c":"Literatura","a":1982,"k":"Recomendación","t":"Se Recomienda: Que las reuniones de AA se coordinen siempre con la “Literatura Aprobada por la Conferencia”.","p":27},{"c":"Literatura","a":1982,"k":"Recomendación","t":"Se Recomienda: Que los grupos se abstengan de editar o fotocopiar literatura de AA sin el permiso correspondiente, puesto que la misma cuenta con derechos registrados y está amparada ante la ley.","p":27},{"c":"Literatura","a":1982,"k":"Recomendación","t":"Se Recomienda: Que las citas escritas de la literatura de A.A. lleven la indicación del libro o folleto de donde han sido tomadas.","p":27},{"c":"Literatura","a":1982,"k":"Recomendación","t":"Se Recomienda: A todos los grupos y miembros utilizar las guías y folletos editados por la OSG para la correcta IP.","p":27},{"c":"Literatura","a":1983,"k":"Recomendación","t":"Se Recomienda: Que toda la literatura que publique la OSG debe llevar el sello de “Aprobado por la Conferencia”, agregando el número y fecha de edición y la anotación de revisada cuando lo sea.","p":27},{"c":"Literatura","a":1983,"k":"Recomendación","t":"Recomienda: Que en la elaboración del boletín se tengan en cuenta aspectos de servicio, información, mensaje de recuperación y situación y noticias de la OSG.","p":27},{"c":"Literatura","a":1984,"k":"Recomendación","t":"Se Recomienda: Que cualquier libro o folleto que hable de A.A. en Colombia sea editado bajo el control de la Corporación de Servicios Generales, producida y revisada previamente por el comité de literatura y sometida a su aprobación por la Conferencia.","p":27},{"c":"Literatura","a":1984,"k":"Recomendación","t":"Se Recomienda: Que en las publicaciones de A.A. no se le dé crédito a ninguna casa editorial.","p":27},{"c":"Literatura","a":1984,"k":"Recomendación","t":"Se Recomienda: Revisar las pruebas de nuevas ediciones antes de autorizar su impresión, esto con el fin de corregir errores o distorsiones en su contenido, como también es necesario mejorar la calidad de la encuadernación de algunos libros.","p":27},{"c":"Literatura","a":1985,"k":"Recomendación","t":"Recomendación: Se ratifica que la única autorizada para editar y fotocopiar la literatura de AA es la OSG que cuenta con derechos registrados y está amparada por la ley. Se Recomienda así mismo que las citas escritas de la literatura de A.A. lleven la indicación del libro o folleto de donde han sido tomadas para darle crédito.","p":27},{"c":"Literatura","a":1985,"k":"Recomendación","t":"Se Recomienda: Que la coordinación de las reuniones se haga únicamente con la literatura de AA. y abstenerse de la venta de literatura que no sea exclusiva de AA.","p":27},{"c":"Literatura","a":1988,"k":"Recomendación","t":"Se Recomienda: Que el Comité de Literatura sugiere a los intergrupos, comités de área y grupos no modificar los precios de literatura establecidos por la OSG, señalando que esta es un medio para pasar el mensaje y no para sostenimiento de los grupos.","p":27},{"c":"Literatura","a":1988,"k":"Recomendación","t":"Se Recomienda: A los intergrupos, comités de área y grupos no modificar los precios de la literatura establecidos por la OSG, señalando que ésta es un medio para pasar el mensaje y no para el mantenimiento de los grupos.","p":27},{"c":"Literatura","a":1991,"k":"Recomendación","t":"Se Recomienda: Dedicar el mes de abril al estudio y divulgación del libro Alcohólicos Anónimos.","p":27},{"c":"Literatura","a":1991,"k":"Recomendación","t":"Se Recomienda: La publicación de los Doce Conceptos y el Manual de Servicio en un solo libro.","p":27},{"c":"Literatura","a":1992,"k":"Recomendación","t":"Se Recomienda: A la OSG editar los Doce Conceptos en tipo cartel, similar a los pasos y tradiciones, para exhibir en los grupos.","p":27},{"c":"Literatura","a":1995,"k":"Recomendación","t":"Se Recomienda: La recopilación de todas las recomendaciones de la Conferencia, que actualicen anualmente y se publiquen.","p":28},{"c":"Literatura","a":1995,"k":"Recomendación","t":"Se Recomienda: Que se publiquen los folletos “AA y las fuerzas armadas”, “Carta a un preso que puede ser alcohólico”, previa revisión y adaptación por parte del comité de literatura de la Junta, de acuerdo con los folletos publicados por la GSO de NY.","p":28},{"c":"Literatura","a":1996,"k":"Recomendación","t":"Se Recomienda: Que la Junta de Custodios solicitarle a la OSG organizar el archivo histórico de Alcohólicos Anónimos en Colombia e igualmente Se Recomienda a las áreas que emprendan este proyecto.","p":28},{"c":"Literatura","a":2000,"k":"Recomendación","t":"Se Recomienda: A la Junta de Servicios Generales le oriente a la OSG para publicar el Informe Final en 45 días, luego de terminada la Conferencia.","p":28},{"c":"Literatura","a":2000,"k":"Recomendación","t":"Se Recomienda: Que en nuestra página Web salga información sobre la revista “AA el mensaje”","p":28},{"c":"Literatura","a":2000,"k":"Recomendación","t":"Se Recomienda: Que, en todos los eventos zonales y nacionales, parte del costo de inscripción sea destinado para entregar a los participantes su valor en literatura. Ejemplo: Una vez el Comité de Finanzas de un congreso tenga determinado el costo de inscripción de $ 30.000, se le incrementen $ 5.000. Para un total de $ 35.000. Los $ 5.000 adicionales serán entregados en literatura como principal recordatorio. La misma será comprada directamente a la OSG.","p":28},{"c":"Literatura","a":2002,"k":"Recomendación","t":"Se Recomienda: Editar un plegable donde se encuentre el funcionamiento del distrito como comité. Se entrega formato modelo.","p":28},{"c":"Literatura","a":2004,"k":"Recomendación","t":"Se Recomienda: Que la OSG edite un plegable exclusivamente hablando del CTO. (Comité Trabajando con Otros). 2005Se Recomienda: Que, en todos los eventos nacionales o zonales, se incluya en la agenda un tema sobre la importancia de la literatura de AA.","p":28},{"c":"Literatura","a":2004,"k":"Recomendación","t":"Se Recomienda: Que cada Delegado a la Conferencia, utilice el formato suministrado por la OSG, para su informe trimestral y anual lo que facilitará una completa claridad en el análisis del mismo.","p":28},{"c":"Literatura","a":2004,"k":"Recomendación","t":"Se Recomienda: Que cada año se realice el mes de la literatura, durante el cual se resalte en los grupos la importancia que tiene, ya que en ella está el verdadero mensaje de Alcohólicos Anónimos y que ese mes sea el de septiembre, durante el cual se conmemora el aniversario de la llegada del mensaje de AA a Colombia.","p":28},{"c":"Literatura","a":2004,"k":"Recomendación","t":"Se Recomienda: Que ningún ente de servicio, con motivo de eventos de AA, produzca y/o distribuya artículos recordatorios tales como: ceniceros, encendedores, pisapapeles, jarros, o similares, ya que el objetivo de AA en tales eventos, es llevar el mensaje de AA, contenido en nuestra literatura, y el mercadeo de tales objetos, no aprobados por la Conferencia, ni producidos por la OSG, no sólo desvían el objetivo espiritual de estas reuniones masivas, sino que afectan notoriamente el bienestar común y la unidad de AA, por las innecesarias polémicas que tales suvenires originan al interior de Nuestra Comunidad.","p":28},{"c":"Literatura","a":2004,"k":"Recomendación","t":"Se Recomienda: Que el libro empastado, que se le envía a los grupos nuevos, para el apadrinamiento y la coordinación de reuniones, sea incluido “preguntas y respuestas sobre apadrinamiento”. (La OSG enviará carta a todos los grupos informando sobre el cambio y que esto se hará en el momento que las existencias se agoten y que además el diseño del folleto cambiará para que se ajuste al tamaño del libro empastado).","p":28},{"c":"Literatura","a":2004,"k":"Recomendación","t":"Se Recomienda: Que en el informe final de la Conferencia del 2000, se incluya un texto que dice que: la Conferencia ni aprueba ni desaprueba el uso del material “regreso a lo básico”. Esta Conferencia no aprueba dicho material porque no está aprobado por la Conferencia.","p":28},{"c":"Literatura","a":2006,"k":"Recomendación","t":"Se Recomienda: Que todos los textos que la OSG ha venido editando a través de los años en Colombia y que no han sido aprobados por la Conferencia queden aprobados a partir de esta, y todos los textos que vayan a ser editados por la OSG sean aprobados por la Conferencia de Servicios Generales.","p":29},{"c":"Literatura","a":2006,"k":"Recomendación","t":"Se Recomienda: Que para no distorsionar el mensaje original de AA, evitemos la proliferación de guías, que no sean de AA, ni aprobadas por la conciencia de grupo, más bien dejemos que nuestros textos originales hablen por sí solos.","p":29},{"c":"Literatura","a":2006,"k":"Recomendación","t":"Se Recomienda: A la Junta de Custodios, establecer los controles necesarios para la revisión final de las ediciones, con el fin que nuestros textos se publiquen sin errores de impresión.","p":29},{"c":"Literatura","a":2007,"k":"Recomendación","t":"Recomendamos: Que la literatura, afiches, comunicaciones, audiovisuales emanados de los Comités de la Conferencia, sean revisados antes de su publicación por el Comité de Literatura de la Junta de Custodios.","p":29},{"c":"Literatura","a":2008,"k":"Recomendación","t":"Se Recomienda: Que las nuevas publicaciones de literatura de Alcohólicos Anónimos y la introducción de nuevos contenidos a la actual, sean sometidas a la aprobación de la Conferencia. Las modificaciones en su presentación y las actualizaciones que se hagan de conformidad con el original que suministra la A.A. Word Services, Inc., podrán realizarse por la OSG previa aprobación del Comité de Literatura de la Junta de Servicios Generales tal como lo establece el concepto once.","p":29},{"c":"Literatura","a":2008,"k":"Recomendación","t":"Se Recomienda: A la OSG actualizar el Manual del Grupo, introduciendo la metodología del inventario de grupo y los planes de trabajo para la formación nuevos grupos y el fortalecimiento de la estructura de los existentes.","p":29},{"c":"Literatura","a":2009,"k":"Recomendación","t":"Se Recomienda: Autorizar a la OSG para que, en unión del comité de publicaciones de la Directiva de Servicios Generales, prepare, edite y comercialice cada año o cada que lo considere conveniente o que las necesidades y la demanda lo exijan, un libro con la selección de Artículos de la Revista AA el Mensaje.","p":29},{"c":"Literatura","a":2009,"k":"Recomendación","t":"Se Recomienda: Autorizar a la OSG para que previos los correspondientes permisos de AA World Services Inc. y el consecuente envío del CD original, de acuerdo con las necesidades y demanda y con la aprobación del Comité de Literatura de la Junta, prepare, edite y comercialice la literatura que la estructura de EEUU tiene traducida al español.","p":29},{"c":"Literatura","a":2011,"k":"Recomendación","t":"Se Recomienda: Que el comité de literatura de la JSG elabore un afiche motivacional alusivo al Comité de Instituciones correccionales, que estará en todos los grupos del país y así concienciar a la membresía para su vinculación a este comité.","p":29},{"c":"Literatura","a":2011,"k":"Sugerencia","t":"Sugerencia: Que los textos, gráficos, diagramas y otros que tengan que ver con la estructura de servicios de AA, sean aprobados por el comité de literatura de la Junta de Custodios.","p":29},{"c":"Literatura","a":2011,"k":"Sugerencia","t":"Sugerencia: Al Comité de Literatura de la J de C que para la próxima edición del libro “La historia de AA en Colombia” se incluya la historia de la llegada del mensaje en aquellas áreas que cumplan 50 o más años de fundadas.","p":29},{"c":"Literatura","a":2012,"k":"Recomendación","t":"Se Recomienda: Que en las próximas ediciones del “Manual del Grupo” aparezca el REM formando parte de la Junta de Servidores del grupo.","p":29},{"c":"Literatura","a":2013,"k":"Recomendación","t":"Se Recomienda: Aprobar el Manual de Imagen Corporativa de Alcohólicos Anónimos de Colombia, que se pone en consideración de la 49 Conferencia","p":30},{"c":"Literatura","a":2014,"k":"Recomendación","t":"Se Recomienda: “Que en una misma publicación se incluyan los manuales de IP, CCP, IT e IC.","p":30},{"c":"Literatura","a":2014,"k":"Recomendación","t":"Se Recomienda: Que se publique un folleto que compile el siguiente material literario: folleto “El Automantenimiento, donde se mezclan la espiritualidad y el dinero”, “El Automantenimiento en AA”, las diferentes modalidades de Automantenimiento y las recomendaciones de la Conferencia vigentes relacionadas con el Automantenimiento.","p":30},{"c":"Literatura","a":2014,"k":"Recomendación","t":"Se Recomienda: Volver a insertar en el Folleto “Es AA para Usted” la introducción a las doce preguntas de auto examen.","p":30},{"c":"Literatura","a":2017,"k":"Sugerencia","t":"Sugerencia: Se diseñe y se publique un afiche sobre la importancia del RSG para ser llevado a cada grupo de todas las áreas.","p":30},{"c":"Literatura","a":2017,"k":"Recomendación","t":"Se Recomienda que, en todos los eventos nacionales o regionales, se incluya en la Agenda un tema sobre la importancia de la literatura de AA.","p":30},{"c":"Literatura","a":2018,"k":"Recomendación","t":"Se Recomienda: Que se actualice el afiche de los Planes de Auto sostenimiento, con las últimas recomendaciones a la fecha.","p":30},{"c":"Literatura","a":2018,"k":"Recomendación","t":"Se Recomienda: Anexar a los folletos del RSG y/o MCD el diagrama de una acción recomendable en las próximas ediciones.","p":30},{"c":"Literatura","a":2019,"k":"Recomendación","t":"Se Recomienda a la Junta de Servicios Generales, elabore un modelo de inventario para los cuerpos de servicio de AA.","p":30},{"c":"Literatura","a":2019,"k":"Moción","t":"Moción de piso","p":30},{"c":"Literatura","a":2019,"k":"Recomendación","t":"Se Recomienda que, en todas las comunicaciones de La Corporación Nacional Servicios Generales y los entes de servicio, cada que se cite algún párrafo o texto de nuestra literatura, se cite la fuente desde dónde fue extractada","p":30},{"c":"Literatura","a":2020,"k":"Recomendación","t":"Se Recomienda: aprobar la impresión del libro “Nuestra Gran Responsabilidad” Se Recomienda: aprobar la impresión del folleto “La Palabra Dios”","p":30},{"c":"Literatura","a":2020,"k":"Recomendación","t":"Se Recomienda: anexar al libro de coordinación (empastado) el enunciado de los Doce conceptos para el servicio mundial forma larga.","p":30},{"c":"Literatura","a":2021,"k":"Nota","t":"Recomendar a la JSG, solicitar la licencia del folleto “Alcohólicos Anónimos para los alcohólicos con problemas de salud mental – y sus padrinos” a la estructura de EE. UU. Y Canadá.","p":30},{"c":"Literatura","a":2021,"k":"Recomendación","t":"Se Recomienda a la JSG tramitar frente a la oficina de Servicios Generales de EE.UU. La aprobación de la traducción al dialecto wayunaiki los siguientes textos: Oración de la Serenidad, el Preámbulo de AA y Esto es AA.","p":30},{"c":"Literatura","a":2022,"k":"Sugerencia","t":"Se sugiere a toda la Estructura de AA en Colombia, acogerse a la recién modificación aprobada por la 71 Conferencia de EE.UU./ Canadá en la cual se cambia hombres y mujeres por personas y… no se pagan honorarios ni cuotas por derechos de admisión, ni cuotas. Nota aclaratoria: Se aplicará para nuevas impresiones.2024","p":31},{"c":"Literatura","a":2022,"k":"Recomendación","t":"Se recomienda: eliminar en el texto Manual de Grupo edición 2023, la palabra “activos” que aparece en la página 35 correspondiente al ítem 12 específicamente en el tema de Finanzas, cuya pregunta está redactada de la siguiente manera ¿Es el grupo sostenido económicamente por todos los miembros activos? Todo esto dentro del tema“Revisión Inventario de Grupo” que inicia en la página Pág 32.","p":31},{"c":"Literatura","a":2022,"k":"Moción","t":"Moción de recordación 2011: Que el Comité de literatura de la JSG elabore un afiche motivacional alusivo al Comité de Instituciones correccionales, que estará en todos los grupos del país y así concienciar a la Membresía para su vinculación a este Comité.","p":31},{"c":"Literatura","a":2022,"k":"Moción","t":"Moción de recordación: Se recomienda a la JSG tramitar frente a la OSG de EE.UU. la aprobación de la traducción al dialecto wuayunaiki, los siguientes textos: Oración de la Serenidad, El Preámbulo de AA y Esto es AA.","p":31},{"c":"Literatura","a":2025,"k":"Recomendación","t":"Se recomienda: Volver a publicar el folleto ‘Cómo se desarrolló la Tradición de AA’. Para conocer que tuvieron que hacer los pioneros antes de que existieran las tradiciones.","p":31},{"c":"Literatura","a":2025,"k":"Recomendación","t":"Se recomienda: Que se publique el Texto Básico en pasta dura, alusivo a la conmemoración de los 90 años de AA en el mundo, con presentación correspondiente a la primera edición, con letra grande.","p":31},{"c":"Política y Admisiones","a":2009,"k":"Recomendación","t":"Se Recomienda, que todas las constancias con informes de minoría, entregados por escrito y debidamente sustentados, sean incluidas en el informe final de la Conferencia.","p":31},{"c":"Política y Admisiones","a":2010,"k":"Recomendación","t":"Recomendación: Que las áreas aledañas, sin importar que pertenezcan a diferentes regiones, se patrocinen entre sí aprovechando sus fortalezas y/o debilidades.","p":31},{"c":"Política y Admisiones","a":2010,"k":"Recomendación","t":"Recomendación: que las comunicaciones internas de la estructura (Reportes y la Junta Informa) se realicen única y exclusivamente vía e-mail, para reducir costos y aprovechar la oportunidad que nos brinda el Internet.","p":31},{"c":"Política y Admisiones","a":2010,"k":"Moción","t":"Moción: Que la Junta de Custodios lidere un proyecto para que a todos los niveles de la estructura pongan en marcha el contenido del Manual de Servicio y los Doce Conceptos de Servicios Mundial.","p":31},{"c":"Política y Admisiones","a":2011,"k":"Recomendación","t":"Se Recomienda que el proyecto de regionalización no tenga límite de tiempo. Se deja a iniciativa de los grupos, distritos, áreas y regiones su consolidación llevando el mensaje de Alcohólicos Anónimos, a donde aún no existe.","p":31},{"c":"Política y Admisiones","a":2012,"k":"Recomendación","t":"Se Recomienda: Que se remplace el texto de la Acción Recomendable del Comité de Política y Admisiones del año 2010 que dice: “Que a partir del año 2011 se invite a un máximo de cinco países a la Conferencia, con un delegado por país, así: nuestros cuatro países patrocinados y el país padrino”, por el siguiente: “Que a partir del año 2013 se invite a un máximo de cinco países a la CSG, con un delegado por país”.","p":31},{"c":"Política y Admisiones","a":2013,"k":"Recomendación","t":"Se Recomienda a la OSG documentar el procedimiento para verificar la existencia de un nuevo grupo, una vez recibido el formulario respectivo diligenciado a través del comité de área para efectos del envió del paquete de literatura, lo cual se realizará en un término no superior a 6 meses. Se exceptúa de lo anterior a los grupos de las áreas inactivas.","p":32},{"c":"Política y Admisiones","a":2013,"k":"Recomendación","t":"Se Recomienda a la Junta de Servicios Generales, que implemente los mecanismos adecuados para socializar y construir colectivamente el plan nacional de fortalecimiento de la estructura de servicios generales de AA Colombia 2014-2020, proyecto que se presenta a la Conferencia de Servicios Generales número 49ª. Una vez acordado con la comunidad el contenido de dicho plan, se presentará el documento final, para su aprobación por la 50ª Conferencia de Servicios Generales. En caso de ser aprobado, serán responsables de su realización todos los integrantes de la estructura de servicios generales. El desarrollo y avance del plan serán informados por el Comité de Políticas y Admisiones de la Conferencia.”","p":32},{"c":"Política y Admisiones","a":2013,"k":"Recomendación","t":"Se Recomienda: Que se lleve a cabo, un evento de orden nacional tendiente a recordar y celebrar “La llegada del mensaje de AA a Colombia”, el cual tendrá lugar cada cinco años, a partir de 2017, en el mes de septiembre. Iniciando en Barranquilla, en lo sucesivo en forma rotativa en diferentes regiones. Será responsabilidad de la Junta de Servicios Generales.","p":32},{"c":"Política y Admisiones","a":2014,"k":"Recomendación","t":"Se Recomienda: Aprobar el Plan Nacional de Fortalecimiento de la Estructura de Servicios Generales 2014 – 2020, la Junta de Custodios coordinará con la OSG la edición y distribución del plan aplicando las políticas vigentes de venta de literatura.","p":32},{"c":"Política y Admisiones","a":2015,"k":"Recomendación","t":"Recomendamos: Que se realicen Los Foros de Servicio en todas las regiones.","p":32},{"c":"Política y Admisiones","a":2016,"k":"Recomendación","t":"Se Recomienda Que cuando se presente una Moción de piso, debe estar secundada por el 10% de los participantes con voto en la reunión anual de la CSG.","p":32},{"c":"Política y Admisiones","a":2017,"k":"Recomendación","t":"Se Recomienda que de acuerdo con los procedimientos establecidos en el Manual de Servicios página M.64 (tamaño media carta) y estando de acuerdo las regiones C y D, se haga el traslado de los grupos Viviendo Sobrio y Sólo por Hoy de la ciudad de Leticia Amazonas de la Región D al Área 3 de la Región C.","p":32},{"c":"Política y Admisiones","a":2017,"k":"Moción","t":"Moción de piso","p":32},{"c":"Política y Admisiones","a":2017,"k":"Recomendación","t":"Se Recomienda que los comités de conferencia tengan asesoría según el tema para mejorar la redacción, orientación y contenido de las propuestas a presentar a plenarias.","p":32},{"c":"Política y Admisiones","a":2019,"k":"Moción","t":"Moción de piso","p":32},{"c":"Política y Admisiones","a":2019,"k":"Recomendación","t":"Se Recomienda: En cada RAC, sean ratificados los Directores no Custodios.","p":32},{"c":"Política y Admisiones","a":2019,"k":"Moción","t":"Moción de piso A la Junta de Custodios que diseñe una Guía Nacional para todas las reuniones regionales y sea socializada y presentada en la Conferencia 56.","p":32},{"c":"Política y Admisiones","a":2020,"k":"Recomendación","t":"Se Recomienda: Que la Junta de Servicios Generales prorrogue el Plan Nacional de Fortalecimiento 2014 – 2020 por cinco años más, evaluar lo actuado y continuar su implementación con el acompañamiento y seguimiento de los Custodios Regionales; se siga evaluando anualmente, a partir del primero de enero del año 2022, según el formato diseñado para tal fin por la Entidad Operativa de Servicios Generales, en su aplicación y en el quinto año una evaluación general.","p":33},{"c":"Política y Admisiones","a":2020,"k":"Moción","t":"Moción de recordación: Que la Junta de Servicios Generales garantice el cumplimiento de lo establecido en nuestro Manual de Servicio, página M93 2° párrafo, que dice: Políticas y Admisiones (No hay comité correspondiente de los Custodios): Responsable de cuestiones de política que tienen que ver con la conferencia y de considerar todas las solicitudes de admisión a la reunión anual de la conferencia de servicios generales. Todos los cambios propuestos al plan de la conferencia, todos los procedimientos encaminados a la ampliación de la conferencia y todo lo que pueda afectar los gastos de la conferencia, se somete al comité de política y admisiones de la conferencia. Este comité está encargado de aprobar o no las solicitudes de Áreas adicionales y evalúan el desarrollo y avance de los planes aprobados en conferencia.","p":33},{"c":"Política y Admisiones","a":2021,"k":"Recomendación","t":"Se Recomienda: a la Junta de Servicios generales realizar un estudio exhaustivo de apadrinamiento, de estructura a estructura y presentar proyecto de Recomendación a la conferencia 58.","p":33},{"c":"Política y Admisiones","a":2022,"k":"Recomendación","t":"Se Recomienda a la JSG determinar y gestionar el apadrinamiento con las estructuras idóneas, para las necesidades actuales y las que surjan en asuntos de Servicios Generales. Para lo anterior se debe contar e informar al Comité de Política y Admisiones. Dicho comité y el Comité Internacional deberán presentar un informe a la Conferencia de Servicios Generales de los avances, desarrollo e implementación.","p":33},{"c":"Política y Admisiones","a":2024,"k":"Recomendación","t":"Se recomienda: a la J.S.G. consultar a la estructura de Estados Unidos y Canadá la forma como se reconocieron y estructuraron los grupos virtuales, para que presenten un proyecto de recomendación a la 61 Conferencia sobre si es viable o no el reconocimiento de estos grupos virtuales en nuestra estructura.","p":33},{"c":"Política y Admisiones","a":2025,"k":"Recomendación","t":"Se recomienda: que las Mociones de Piso para ser discutidas en la RAC, deben estar secundadas por mayoría simple de los conferencistas.","p":33},{"c":"Política y Admisiones","a":2026,"k":"Recomendación","t":"Se recomienda a la Junta de Custodios que implemente un Plan Nacional de Acción durante 5 años a partir del 2027 y se presente en la 63 RAC, dando a conocer los resultados en las reuniones anuales de las Conferencias siguientes, teniéndose en cuenta únicamente por la Junta de Custodios el Plan de Acción presentado por el Comité de Política y Admisiones.","p":33},{"c":"Congresos, Eventos y Foros","a":1976,"k":"Nota","t":"Recomendación. Este comité considera que debe ratificarse la Recomendación de la pasada conferencia en el sentido de que sea el custodio y los delegados de cada zona, quienes de común acuerdo señalen las sedes de los congresos zonales.","p":33},{"c":"Congresos, Eventos y Foros","a":1986,"k":"Recomendación","t":"Se Recomienda: A los organizadores de congresos zonales no pasar sombrero en ninguna de sus reuniones, puesto que estos se financian con las inscripciones y aportes especiales.","p":34},{"c":"Congresos, Eventos y Foros","a":1990,"k":"Recomendación","t":"Se Recomienda: que a partir de la VII Convención de AA que se debe realizar en 1999, la designación de la sede se haga en forma rotatoria por zonas así: 1º la zona E, 2º la zona A, y después la B, etc.","p":34},{"c":"Congresos, Eventos y Foros","a":1990,"k":"Recomendación","t":"Se Recomienda: debido a los problemas de alojamiento que se presentan al fin del año Que el congreso de la zona A, se realicen en el bimestre septiembre-octubre, pero en un mes distinto al que se celebra el congreso de la zona D.","p":34},{"c":"Congresos, Eventos y Foros","a":2025,"k":"Recomendación","t":"Se recomienda: que los eventos nacionales y regionales que requieran contratos a nombre de la Corporación sean previamente consultados con el Departamento Jurídico para ser aprobados por la Junta de Servicios Generales y Comité de Eventos Nacionales.","p":34},{"c":"Custodios y Nominaciones","a":2004,"k":"Recomendación","t":"Se Recomienda: Que el Comité de Agenda y Políticas, después de conocer las hojas de vida de los nuevos delegados electos, determine e informe oportunamente (mes de enero) sobre la conformación de los comités, anexando dirección, teléfono y si tiene correo electrónico. Lo anterior para que haya una previa y mayor comunicación entre los miembros de cada comité.","p":34},{"c":"Custodios y Nominaciones","a":2005,"k":"Recomendación","t":"Se Recomienda: que la tercera Recomendación del año 1993 que dice: “Se Recomienda que en la elección de custodios clase B, se tenga en cuenta en lo posible, que los candidatos hayan prestado el servicio de delegados y además su trayectoria y espíritu de servicio, junto con su tiempo de abstención y actividad profesional”, se requiera que el candidato haya sido delegado a la Conferencia de Servicios Generales. (Incluido en el manual de servicio edición 2014)","p":34},{"c":"Custodios y Nominaciones","a":2013,"k":"Sugerencia","t":"Se sugiere a la Junta de Servicios Generales que las hojas de vida de los candidatos a Directores no Custodios, miembros para la Junta Directiva de Servicios Generales y de AA El Mensaje sean enviadas al Comité de Nominaciones de la Conferencia de Servicios Generales con 30 días de anticipación para darles el respectivo procedimiento.","p":34},{"c":"Custodios y Nominaciones","a":2018,"k":"Recomendación","t":"Se Recomienda: Que las hojas de vida presentadas al Comité de Nominaciones de la CSG, sean diligenciadas en un formato establecido previamente por la Oficina de Servicios Generales. Así mismo, crear y/o poner en vigencia un formato para transcripción de las partes relevantes del acta electiva adjunta del candidato postulado al servicio","p":35},{"c":"Custodios y Nominaciones","a":2018,"k":"Recomendación","t":"Se Recomienda: Que se retire la Recomendación del año 2006 del Comité de Nominaciones: “Se Recomienda al Comité de Nominaciones de la Junta de Custodios que en la escogencia del custodio clase B, se tenga en cuenta, en lo posible, la rotación de las diferentes áreas, para que se cumpla el principio de rotación”.","p":35},{"c":"Custodios y Nominaciones","a":2019,"k":"Moción","t":"Moción de recordación. Que se cumpla con el formato aprobado en la 54ª Conferencia para las hojas de vida de los aspirantes a Custodio. Que la hoja de vida que no cumpla con el requisito sea rechazada.","p":35},{"c":"Custodios y Nominaciones","a":2026,"k":"Nota","t":"Que teniendo en cuenta que la [nombre omitido], Custodia Clase A, no fue ratificada, se solicita mediante este proyecto de recomendación en esta conferencia, la presentación de hoja de vida y la ratificación de la Custodia Clase A faltante, dado que al Comité de Nominaciones de la Conferencia llegaron tres hojas de vida aprobados por la junta para su consideración. Nota: una vez aprobado el proyecto en plenaria se presentó la Hoja de vida de [nombre omitido] para el servicio de Custodia Clase A y fue ratificada por el pleno de la Conferencia.","p":35},{"c":"Informe y Carta","a":2013,"k":"Recomendación","t":"Se Recomienda: que los ajustes y modificaciones que deban realizarse al Manual de Servicio de Alcohólicos Anónimos se efectúen a través de proyectos de Acción Recomendables que lleguen al Comité de Informe y Carta y que este comité presente a la Conferencia de Servicios Generales en pleno para su aprobación. Que en lo sucesivo no se apruebe la creación de comités transitorios para modificación del manual.","p":35},{"c":"Informe y Carta","a":2013,"k":"Recomendación","t":"Se Recomienda Que las modificaciones al Manual de Servicio empiecen a regir cuando la CSG lo disponga y aparezcan en el Manual de Servicio en cada nueva edición.","p":35},{"c":"Informe y Carta","a":2013,"k":"Recomendación","t":"Se Recomienda que el artículo 6 de los Estatutos de la Corporación de Servicios Generales de Alcohólicos Anónimos de Colombia – Junta de Servicios Generales quede redactado de la siguiente manera: “Artículo 6º: la Carta Constitutiva de la Conferencia clasifica a los miembros custodios en dos categorías: no alcohólicos y alcohólicos. Los Custodios no alcohólicos son cuatro (4) y se designan en estos estatutos como miembros Custodios Clase A…” En lo demás queda igual. Esto deberá incluirse en la parte correspondiente al Manual y el nuevo Custodio clase A deberá ratificarse en la próxima Reunión Anual de la Conferencia.","p":35},{"c":"Informe y Carta","a":2013,"k":"Recomendación","t":"Se Recomienda: que se nombren las áreas de la siguiente manera: Área 2 Región D Palmira Área 6 Región E Aburra Sur y Occidente. Área 7 Región E Medellín Norte","p":35},{"c":"Informe y Carta","a":2014,"k":"Recomendación","t":"Se Recomienda: que en los estatutos de la Corporación Nacional de Servicios Generales de AA se incluya la figura del Revisor Fiscal.","p":36},{"c":"Informe y Carta","a":2016,"k":"Recomendación","t":"Recomendación: Incluir dentro del Manual de Servicio, la figura del “Custodio Emérito” a los presidentes de La JSG, que en razón de la rotación han salido. Y que la JSG considere merecedores de esta distinción. La JSG, cuando lo considere necesario, acudirá a su experiencia y sabiduría, invitándolos a participar en las reuniones de La JSG y conferencia con voz sin voto.","p":36},{"c":"Informe y Carta","a":2016,"k":"Recomendación","t":"Recomendación: CUSTODIOS GENERALES: Suprimir la parte final del párrafo contenida en el MANUAL DE SERVICIO, en la pág. M102, donde se lee: “...Pueden reemplazar a custodios Regionales según se necesite o se pida” por “...Pueden reemplazar a custodios regionales en caso de que se necesite…” se suprime las palabras “según” o “se pida”","p":36},{"c":"Informe y Carta","a":2017,"k":"Nota","t":"Los siguientes son los textos propuestos que fueron aprobados del Manual de Servicio: M20 TC / M29 TMC. Custodio: un miembro de la Junta de Servicios Generales, ocho custodios son miembros de AA; Cuatro no son alcohólicos. M36 TC / M51 TMC. A veces hay una persona en el área, suele ser el secretario de área, que se encarga de facilitar la información de la OSG sobre cambio de información de distrito. M49 TC / M68 TMC En algunas áreas hoy en día, hay secretarios de oficina que preparan y mantienen información de todos los grupos del área en los que se incluyen datos tales como: nombre del grupo, lugar y horas de reunión, nombre del RSG o del contacto del grupo. Mantiene apuntados y archivados los nombres, direcciones y números de teléfono de los RSG, los MCD, los servidores del área, del distrito y los coordinadores de los comités de servicio del área. También prepara las etiquetas de correo para las publicaciones del área, el boletín de área, por ejemplo, o para él envió de las actas. Para realizar este trabajo, es muy útil ser una persona bien organizada y saber utilizar los computadores M51 TC / M71 TMC. Métodos de Automantenimiento: a continuación, aparecen algunos métodos que han posibilitado a las áreas seguir siendo solventes y eficaces: Se reciben contribuciones voluntarias en la asamblea y en las reuniones de distrito. M52 TC / M74 TMC. Recordar a los MCD y RSG que informen a los distritos, grupos y miembros sobre AA el mensaje y la literatura aprobada por la Conferencia. Que se corrija en el manual en la página M104 TMC, el número actual de comités permanentes de la junta de custodios es Once (11)","p":36},{"c":"Informe y Carta","a":2017,"k":"Moción","t":"Moción de piso aprobado.","p":36},{"c":"Informe y Carta","a":2017,"k":"Recomendación","t":"Se Recomienda: que los ajustes a manual de Servicio que sean de forma o de carácter legal no se constituyan en acciones recomendables, sino que el comité de informe y carta de la CSG, lo envíe directamente al comité de literatura de la Junta Directiva de Servicios Generales, para su implementación.","p":36},{"c":"Informe y Carta","a":2017,"k":"Recomendación","t":"Se Recomienda: unificar términos en los manuales, distrito es una división geográfica (M30- TMC), distrito es una entidad geográfica (M46-TMC). Que quede como dice en el lenguaje de la Conferencia; el distrito es una división geográfica (M30-TMC)","p":36},{"c":"Informe y Carta","a":2017,"k":"Sugerencia","t":"Sugerencia: Tener en cuenta el lenguaje de la conferencia aprobado en la última edición del Manual de servicio (Página M20-TC) en las interpretaciones de todos los asuntos de la Conferencia.","p":37},{"c":"Informe y Carta","a":2018,"k":"Recomendación","t":"Se Recomienda: Corregir el diagrama de una Acción Recomendable y anexarlo al Manual de Servicio en la página M87 – TMC.","p":37},{"c":"Informe y Carta","a":2019,"k":"Recomendación","t":"Se Recomienda: Se incluya en el Manual de Servicio en la página M34, lo siguiente: Cuando se presente un solo candidato a un servicio, para lo cual no es aplicable el procedimiento del Tercer Legado, esta elección debe hacerse en una sola votación secreta por el sí o por el no, y debe alcanzar las dos terceras partes o más para ser elegido.","p":37},{"c":"Informe y Carta","a":2019,"k":"Sugerencia","t":"Sugerencia: Suprimir del Manual de Servicio de la página M42 el texto Paquete del RSG (cuarto párrafo). Entrará en vigencia, a partir de la fecha y se hará el cambio en la próxima edición del Manual de Servicio","p":37},{"c":"Informe y Carta","a":2019,"k":"Recomendación","t":"Se Recomienda: La Junta de Custodios que diseñe una Guía Nacional para todas las reuniones regionales y sea socializada y presentada en la Conferencia 56","p":37},{"c":"Informe y Carta","a":2019,"k":"Moción","t":"Moción de piso","p":37},{"c":"Informe y Carta","a":2019,"k":"Recomendación","t":"Se Recomienda incluir en el Manual de Servicio, lo siguiente: Para todo proceso de presentación de servidores (Custodios Clase A, Custodio de Servicios Generales y Directores no Custodios), si se presenta alguna objeción, se abre el debate y si no es retirada la objeción, se somete a votación secreta por el si o por el no de todos los Conferencistas y debe alcanzar las dos terceras partes o más de los votos para ser aprobada.","p":37},{"c":"Informe y Carta","a":2020,"k":"Recomendación","t":"Se Recomienda: Incluir en el Manual de Servicios de AA Colombia, en el capítulo noveno “La Junta de Servicios Generales”, antes de la composición, Pág. M95, lo siguiente: Enunciado de misión, visión y acción de la Junta de Servicios Generales Para guiar nuestro sentido de responsabilidad, los Custodios de la Juntas de Servicios Generales han adoptado el siguiente enunciado de misión, visión y acción: Misión: Servir a la Comunidad de Alcohólicos Anónimos Visión: Proporcionamos a la comunidad una dirección clara y efectiva. Responsables ante la comunidad por medio de la Conferencia de Servicios Generales. Nos ocupamos de todos los asuntos que impactan en el objetivo primordial de la Comunidad: llevar el mensaje al Alcohólico que aún sufre. Acción: En todas nuestras deliberaciones y decisiones nos dejamos guiar por los Doce Pasos, Doce Tradiciones y Doce Conceptos.","p":37},{"c":"Informe y Carta","a":2020,"k":"Recomendación","t":"Se Recomienda: Modificar el texto que está en la pág. M133 del Manual de Servicios que dice: La mayoría de las áreas tienen un comité de AA el Mensaje, participan activamente en los trabajos encaminados a poner AA el Mensaje a disposición de los demás comités de servicio, tales como centros correccionales, de tratamiento y cooperación con la comunidad profesional. Cambiar por: La mayoría de las áreas tienen un coordinador de AA el Mensaje, quien desarrolla actividades con los diferentes REM de los grupos y los distritos. Acorde con la Moción de recordación de la 55 CSG de 2019 que dice: “Revisar y modificar el Manual de gestión del REM en la medida que no aparezca como comité sino como representante” Ver pág. M69. “Un coordinador de AA el Mensaje”","p":37},{"c":"Informe y Carta","a":2020,"k":"Recomendación","t":"Se Recomienda: Cambiar de la Pág. M64 en directrices para cambiar cabecera de área lo siguiente: Aprobación en asamblea Regional Cambiar por en texto: Avalar en la reunión Regional.","p":38},{"c":"Informe y Carta","a":2020,"k":"Recomendación","t":"Se Recomienda: Modificar en el Manual de Servicio en la Pág. M102 en su último párrafo, de la siguiente manera. El texto actual dice “El comité de Nominaciones de los custodios revisa la lista de los candidatos para comprobar su elegibilidad y durante la conferencia, algún tiempo antes de la sesión electoral, los delegados de cada área se reúnen y van reduciendo las listas hasta que quede un solo candidato por Region” Texto que se propone adicionar o modificar “El Comité de Nominaciones de los custodios revisa la lista de los candidatos para comprobar su elegibilidad y durante la Conferencia, algún tiempo antes de la sesión electoral, los delegados de cada área y el custodio de la región, se reúnen y van reduciendo las listas hasta que quede un solo candidato por Region”","p":38},{"c":"Informe y Carta","a":2020,"k":"Recomendación","t":"Se Recomienda: Se propone el siguiente Proyecto de Recomendación de adición al Manual de Servicio en la pág.M31 Lenguaje de la Conferencia con enmienda aprobada por el comité","p":38},{"c":"Informe y Carta","a":2020,"k":"Recomendación","t":"Se Recomienda al comité de informe y carta de la Conferencia favor anexar al Manual de Servicio el significado de las frases: Moción de recordación, Moción de orden y Moción de piso, a incluirse en la pág. M31 Lenguaje de la Conferencia. Se dio lectura a la carta enviada por el comité del área 4 Region A, territorio norte, sometiéndose a debate y consideración ante la 56 Conferencia de Servicios Generales lo siguiente: Se realizaron cambios en el Manual por parte del comité de informe y carta en años anteriores, sin que fueran aprobados por la Conferencia de Servicios Generales. Razón por la cual se realizó revisión de las recomendaciones aprobadas por la Conferencia desde el año 2014 (manual anterior, tercera edición) evidenciadas en la página web de la Corporación, modificaciones que aparecen en el actual Manual de Servicios (cuarta edición, 2018 -2020) y que, de acuerdo con nuestro debate y deliberación en el comité de la actual Conferencia están conformes así: En la versión anterior del Manual 2014, en la pág. M63, párrafo 3, en el subtítulo Congresos, Foros y Eventos de la Region, se agregó: “El Custodio General del Territorio donde pertenece la Región podrá pertenecer al comité ejecutivo del evento” En el mismo párrafo ser cambió la frase: “por lo general, no se celebran reuniones de asamblea durante estos eventos” y se escribió: “por lo general, no se celebran Reuniones Regionales durante estos eventos” En el capítulo 6 sobre el Delegado, en la pág. M73, en el subtítulo: Responsabilidad, cambiaron la Frase: Asistir a todas las asambleas y reuniones de servicio del área y de la Region (en la cual asistan el custodio de la Region, el correspondiente Custodio General del Territorio y los delegados de la Región) “ Y por último en el capítulo 9, sobre la Junta de Servicios Generales, en la pág. M104, segundo párrafo se cambió en la Frase: “Se somete al Comité de Nominaciones de las Custodios la Hoja de Vida y de Servicios de un candidato competente, que ha servido por dos años por lo menos como miembro de la Junta Directiva de Servicios Generales o de la …” Por “ Se somete al Comité de Nominaciones de los Custodios la Hoja de Vida y de Servicios de un candidato competente, que ha servido por un año por lo menos como miembro de la Junta Directiva de Servicios Generales o de la ...”","p":38},{"c":"Informe y Carta","a":2021,"k":"Recomendación","t":"Se Recomienda, a la Conferencia de Servicios Generales incluir en el Manual de Servicio y Doce Conceptos para el Servicio Mundial en la página M37, el siguiente texto después del tema “Cómo estimular el interés en los Servicios Generales” y antes del tema “Instrumentos Disponibles en la OSG”, el principio de rotación que aparece en el manual de Estados Unidos y Canadá 2016 - 2020 pág. S26. EL PRINCIPIO DE LA ROTACIÓN: “EL PRINCIPIO DE LA ROTACION” Tradicionalmente, la rotación asegura que los servicios, como casi todo lo demás en AA, se repartan para que todos los miembros puedan compartir. Muchos servicios tienen suplentes que se pueden incorporar a los servicios, si se necesitan. Dejar un servicio de AA que amamos puede ser difícil. Si hemos estado haciendo un buen trabajo, si sinceramente no vemos a nadie alrededor que esté dispuesto, cualificado o que disponga del tiempo necesario para hacerlo y si nuestros amigos están de acuerdo, es especial-mente duro. Pero puede ser un verdadero paso hacia adelante en el desarrollo – un verdadero paso hacia la humildad que es, para algunas personas, la esencia espiritual del anonimato. El anonimato en la comunidad significa, entre otras cosas, que renunciamos al prestigio personal por cualquier trabajo de A.A. que hagamos para ayudar a los alcohólicos. Y en el espíritu de la duodécima tradición, nos recuerda siempre “anteponer los principios a las personalidades”. A muchos miembros que salen de su servicio les resulta muy gratificante dedicar algún tiempo a compartir su experiencia con la persona que entra al servicio. La rotación ayuda a traernos recompensas espirituales mucho más duraderas que la fama. Al no haber en juego ningún “estatus” de A.A no necesitamos competir por títulos o alabanzas – tenemos completa libertad para servir según se nos necesite”. 2. En la 56ª Conferencia de Servicios Generales aprobamos la siguiente Recomendación: “Modificar el Manual de Servicio en la página M-102, en su último párrafo, de la siguiente manera”. EL TEXTO ACTUAL DICE “El Comité de Nominaciones de los custodios revisa la lista de los candidatos para comprobar su elegibilidad y durante la Conferencia, algún tiempo antes de la sesión electoral, los delegados de cada área se reúnen y van reduciendo las listas hasta que quede un solo candidato por Región”. TEXTO QUE SE PROPONE ADICIONAR Y MODIFCAR “El Comité de Nominaciones de los custodios revisa la lista de los candidatos para comprobar su elegibilidad y durante la conferencia algún tiempo antes de la sesión electoral, los delegados de cada área y el custodio de la región, se reúnen y van reduciendo las listas hasta que quede un solo candidato por región”. Teniendo en cuenta lo anterior y dado que aprobamos modificar el Manual desconociendo lo establecido en la Carta Constitutiva, recomendamos a la Conferencia de Servicios Generales RETIRAR esta Recomendación.","p":39},{"c":"Informe y Carta","a":2023,"k":"Recomendación","t":"Se Recomienda al Comité de Informe y Carta Constitutiva corregir en el Manual de Servicio pág. M53 que se suprima el segundo ítem: requisitos para elección de MCD, dos palabras “Como delegado”. Quedando el párrafo así (Para ser MCD se debe llevar sobrio un tiempo suficiente, por lo general, cuatro o más años).","p":39},{"c":"Informe y Carta","a":2024,"k":"Recomendación","t":"Se recomienda: que en toda nuestra literatura donde aparezca transcrita la Tradición Once, sean eliminadas las palabras televisión e internet. “La Entidad Operativa de Servicios Generales es la entidad que selecciona el personal de la OSG, dirige los servicios de la OSG y está encargada de publicar los libros y folletos aprobados por la Conferencia. Pág. M30 - Edición 2022. Cambiar por: “La Entidad Operativa de Servicios Generales es la entidad que apoya los diferentes departamentos de la OSG y está encargada de la revisión de libros y folletos aprobados por la Conferencia”.","p":39},{"c":"Informe y Carta","a":2024,"k":"Recomendación","t":"Se recomienda: a la Junta de servicios Generales actualizar el próximo Manual de Servicio y Doce Conceptos para el Servicio Mundial, edición 6, 2025 en el formato que tienen las estructuras de Estados Unidos/Canadá y México. Elaboración de la síntesis de la experiencia de la adecuación del Manual de Servicio. Aprobado en 2007.","p":39},{"c":"Revista AA El Mensaje","a":2009,"k":"Moción","t":"Moción: Que se continúe en las áreas con la creación de los Comités de la Revista AA El Mensaje y que estos estén en cabeza preferiblemente del Delegado actual o ex delegados.","p":40},{"c":"Revista AA El Mensaje","a":2010,"k":"Moción","t":"Moción: que se tenga en cuenta publicar en el último número del año los nuevos precios de la revista y de las suscripciones y en caso de no haber cambios, informar que continúan los mismos precios hasta nueva orden.","p":40},{"c":"Revista AA El Mensaje","a":2010,"k":"Moción","t":"Moción: Se sugiere a los grupos y cuerpos de servicio que elijan su REM. Así nos iremos preparando para la nueva etapa de la revista El Mensaje.","p":40},{"c":"Revista AA El Mensaje","a":2012,"k":"Recomendación","t":"Recomendación: Que la Junta Directiva de AA El Mensaje, a través de su oficina, amplíe el portafolio de sus productos, mediante el diseño, producción y comercialización de nuevos materiales.","p":40},{"c":"Revista AA El Mensaje","a":2012,"k":"Recomendación","t":"Recomendación: Que la Junta Directiva de AA El Mensaje, con el fin de ampliar la difusión de nuestra reunión impresa, genere una política de apadrinamiento consistente en que un miembro de AA, patrocine con una suscripción de nuestra revista a una persona y/o institución.","p":40},{"c":"Revista AA El Mensaje","a":2013,"k":"Recomendación","t":"Recomendación: a la Junta de Servicios Generales organizar un encuentro anual en el mes de mayo que convoque a los R.E.M. (Representantes de la Revista “AA El Mensaje”), para impulsar la difusión, circulación de la revista y sus productos asociados y capacitar a dichos servidores.","p":40},{"c":"Revista AA El Mensaje","a":2013,"k":"Recomendación","t":"Se Recomienda: a la Junta de Custodios realizar dentro de la celebración de la llegada del mensaje a Colombia, la celebración de los aniversarios del nacimiento de la revista AA El Mensaje.","p":40},{"c":"Revista AA El Mensaje","a":2013,"k":"Recomendación","t":"Se Recomienda: a la Junta de Custodios, la creación del folleto denominado “Manual de gestión del R.E.M.” que incluya las responsabilidades de este servidor.","p":40},{"c":"Revista AA El Mensaje","a":2014,"k":"Recomendación","t":"Se Recomienda: que agosto sea declarado el mes de la Revista A.A. El Mensaje","p":40},{"c":"Revista AA El Mensaje","a":2017,"k":"Recomendación","t":"Se Recomienda: Que se incluya en la revista de AA El Mensaje las Doce Preguntas.","p":40},{"c":"Revista AA El Mensaje","a":2017,"k":"Recomendación","t":"Se Recomienda en la sección de la revista AA El Mensaje ‘Si las paredes hablaran’, se agregue en las fotos del grupo la frase Sede del grupo…","p":40},{"c":"Revista AA El Mensaje","a":2018,"k":"Moción","t":"Moción de recordación: A las áreas que no tienen sus respectivos REM, elegirlo","p":40},{"c":"Revista AA El Mensaje","a":2018,"k":"Recomendación","t":"Se Recomienda Revisar y modificar el Manual de Gestión del REM en la medida en que no aparezca como comité, sino como representante.","p":40},{"c":"Revista AA El Mensaje","a":2019,"k":"Moción","t":"Moción de recordación.","p":41},{"c":"Revista AA El Mensaje","a":2019,"k":"Recomendación","t":"Se Recomienda: A la Junta de Servicios Generales ejecutar la Recomendación aprobada en la Conferencia 54 que dice: revisar y modificar el Manual de Gestión del REM en la medida en que no aparezca como comité, sino como representante.","p":41},{"c":"Revista AA El Mensaje","a":2020,"k":"Recomendación","t":"Se Recomienda: Modificar el texto de la pág. M29 que dice: AA El Mensaje: es la Revista de Alcohólicos Anónimos de Colombia publicada por la Oficina de AA El Mensaje. Cambiar por: AA El Mensaje: es la Entidad Operativa encargada de publicar la Revista de Alcohólicos Anónimos de Colombia “AA El Mensaje y los demás productos de ella.","p":41},{"c":"Revista AA El Mensaje","a":2020,"k":"Recomendación","t":"Se Recomienda: suspender la edición del Manual de Gestión del REM y reemplazarlo por un plegable que contenga la información básica del REM.","p":41},{"c":"Revista AA El Mensaje","a":2020,"k":"Recomendación","t":"Se Recomienda: permitir la autonomía del comité editor de la revista AA El Mensaje para publicar las secciones y los artículos que consideren pertinentes.","p":41},{"c":"Revista AA El Mensaje","a":2021,"k":"Moción","t":"Moción de recordación. Que la junta Directiva de AA el Mensaje genere “la política de apadrinamiento” correspondiente a la Recomendación de 2012 que dice: Que la Junta Directiva de AA el Mensaje con el fin de ampliar la difusión de nuestra reunión impresa, genere una política de apadrinamiento consistente en que un miembro de AA patrocine con una suscripción de nuestra revista a una persona y/o institución.","p":41},{"c":"Revista AA El Mensaje","a":2024,"k":"Recomendación","t":"Se recomienda: Que los títulos de los productos de la revista AA El Mensaje se publiquen en la misma revista.","p":41},{"c":"Revista AA El Mensaje","a":2025,"k":"Recomendación","t":"Se recomienda: a los grupos que deseen o puedan adquirir 5 revistas cada 3 meses para obsequiar y que de ser posible el valor sea incluido en el presupuesto mensual del grupo. Esta adquisición sería adicional a la inscripción que cada grupo posee.","p":41},{"c":"Revista AA El Mensaje","a":2026,"k":"Recomendación","t":"Se recomienda: a la Junta de Custodios que encargue a la Entidad Operativa AA El Mensaje la edición especial e Impresión de un libro titulado “Soy Mujer en AA” colección de testimonios de la mujer en nuestra comunidad publicados en la Revista AA El Mensaje.","p":41},{"c":"Archivo Histórico","a":2025,"k":"Recomendación","t":"Se recomienda: que todos los informes finales de las 61ª. Conferencias realizadas hasta la fecha, así como los que se generen en adelante como resultado de futuras conferencias, estén disponibles en formato PDF en nuestra página web. Estos documentos permiten reconstruir la historia de las áreas, por lo que constituyen un valioso material de consulta con gran relevancia histórica. Excluir las últimas páginas que tienen los nombres y direcciones de los servidores y omitir los apellidos donde aparezcan, en cambio reemplazar por la inicial.","p":41},{"c":"Archivo Histórico","a":2025,"k":"Recomendación","t":"Se recomienda: que la JSG mediante su Comité de Archivo Histórico, programe cada año en el mes de septiembre una reunión virtual con la participación de veteranos para conmemorar la llegada del mensaje de AA a Colombia, invitando a todas las regiones y membresía del país, así mismo a la comunidad internacional.","p":42}];
